t_wa_status.source:
async function handleWaWebhook(request, env, url) {
  /* Meta's one-time verification handshake */
  if (request.method === 'GET') {
    const p = url.searchParams;
    if (p.get('hub.mode') === 'subscribe' && verifyOk(env, p.get('hub.verify_token'))) {
      return new Response(p.get('hub.challenge') || '', { status: 200 });
    }
    return new Response('forbidden', { status: 403 });
  }
  /* No app secret for HMAC — the shared token rides the callback URL instead */
  if (!verifyOk(env, url.searchParams.get('t'))) {
    return new Response('forbidden', { status: 403 });
  }

  let payload;
  try { payload = await request.json(); } catch { return new Response('ok', { status: 200 }); }
  /* 22/10: anything Meta tells us that is not a message/status (template
     approvals, number quality, account limits) goes to the audit log verbatim */
  try {
    for (const entry of (payload && payload.entry) || []) for (const ch of entry.changes || []) {
      const f = String(ch.field || ''); const v = ch.value || {};
      if (f && f !== 'messages') stream(env, { kind: 'meta', area: 'מטא', action: '🟦 ' + f + (v.event ? ' · ' + v.event : '') + (v.message_template_name ? ' · ' + v.message_template_name : '') + (v.current_limit ? ' · ' + v.current_limit : ''), ok: !/REJECTED|FLAGGED|RED|DISABLED|RESTRICT/i.test(JSON.stringify(v)), review: /REJECTED|FLAGGED|RED|DISABLED|RESTRICT/i.test(JSON.stringify(v)), detail: JSON.stringify(v).slice(0, 1500), data: { field: f, value: v } }).catch(() => {});
    }
  } catch {}

  /* Meta also posts delivery STATUSES here (sent/delivered/read/failed). We
     never read them, so a template Meta accepted and then failed to deliver
     was invisible — exactly Richard's "I didn't get the WhatsApp" on 05/09.
     A failed delivery is a red row; nothing else about statuses is kept. */
  try {
    for (const entry of (payload && payload.entry) || []) {
      for (const ch of entry.changes || []) {
        for (const st of (ch.value && ch.value.statuses) || []) {
          /* every status lands in the message log line of that id: delivered,
             read, failed ('sent' is already the row itself) */
          try {
            const pid = String(((ch.value || {}).metadata || {}).phone_number_id || '');
            const stab = isGuestPhone(env, pid) ? 'msg_guests' : 'msg_clients';
            const when = ilTime(st.timestamp ? new Date(Number(st.timestamp) * 1000) : new Date());
            const cat = st.pricing ? `${st.pricing.category || ''}${st.pricing.billable === false ? ' (לא בתשלום)' : ''}` : '';
            /* the inbox bubble gets the same status (✓ / ✓✓ / read / failed) */
            try {
              const lk = st.id && env.RATE ? await env.RATE.get('wamid2log:' + st.id) : null;
              if (lk) {
                const cur = JSON.parse(await env.RATE.get(lk) || 'null');
                if (cur) {
                  const rank = { sent: 1, delivered: 2, read: 3, failed: 9 };
                  if ((rank[st.status] || 0) >= (rank[cur.status] || 0)) {
                    cur.status = st.status; cur.status_at = Number(st.timestamp) * 1000 || Date.now();
                    if (st.status === 'failed') { const e0 = (st.errors && st.errors[0]) || {}; cur.error = `${e0.code || ''} ${e0.title || ''}`.trim(); }
                    await env.RATE.put(lk, JSON.stringify(cur));
                  }
                }
              }
            } catch {}
            /* 22/10 Richard: the dashboard shows נשלח / התקבל / נקרא per guest,
               and a Meta refusal is never shown as "sent". wst:<token>:<wave>:<phone> */
            try {
              const m2 = st.id && env.RATE ? JSON.parse(await env.RATE.get('wamid:' + st.id) || 'null') : null;
              if (m2 && m2.token && m2.phone) {
                const rank = { sent: 1, delivered: 2, read: 3, failed: 9 };
                const k2 = `wst:${m2.token}:${m2.wave || 1}:${m2.phone}`;
                const cur2 = await env.RATE.get(k2).catch(() => null);
                if ((rank[st.status] || 0) >= (rank[cur2] || 0)) await env.RATE.put(k2, st.status, { expirationTtl: 120 * 86400 }).catch(() => {});
              }
              const e1 = (st.errors && st.errors[0]) || {};
              stream(env, { kind: 'wa_status', area: stab === 'msg_guests' ? 'שיר' : 'נועה', action: (st.status === 'read' ? '👁 נקרא' : st.status === 'delivered' ? '✓✓ נמסר' : st.status === 'failed' ? '⛔ נכשל' : '✓ ' + st.status) + ' · ' + String(st.recipient_id || ''), ok: st.status !== 'failed', review: st.status === 'failed', phone: String(st.recipient_id || ''), token: m2 && m2.token ? m2.token : '', detail: st.status === 'failed' ? `${e1.code || ''} ${e1.title || ''} ${(e1.error_data && e1.error_data.details) || ''}`.trim() : (cat || ''), data: { wamid: st.id, status: st.status, meta_ts: st.timestamp, wave: m2 ? m2.wave : '', pricing: st.pricing || null }, cost: st.status === 'delivered' && st.pricing && st.pricing.billable !== false ? ({ utility: 0.02, marketing: 0.13, authentication: 0.05, service: 0 }[String(st.pricing.category || '').toLowerCase()] ?? 0.02) : 0 }).catch(() => {});
            } catch {}
            if (st.status === 'delivered') await logUpdate(env, stab, st.id, { delivered: 'כן ' + when, phone: st.recipient_id || '', category: cat });
            else if (st.status === 'read') await logUpdate(env, stab, st.id, { read: 'כן ' + when, phone: st.recipient_id || '', category: cat });
            else if (st.status === 'failed') {
              const e0 = (st.errors && st.errors[0]) || {};
              await logUpdate(env, stab, st.id, { sent: 'נכשל במסירה ' + when, phone: st.recipient_id || '',
                error: `${e0.code || ''} ${e0.title || ''} ${(e0.error_data && e0.error_data.details) || ''}`.trim() });
            }
          } catch {}
          if (st.status !== 'failed') continue;
          const err = (st.errors && st.errors[0]) || {};
          if (st.id && await seenOnce(env, 'wafail:' + st.id)) continue;
          /* was this a wave invitation? then the guest is NOT sent — reopen them */
          let retry = '';
          try {
            const m = st.id && env.RATE ? JSON.parse(await env.RATE.get('wamid:' + st.id) || 'null') : null;
            if (m && m.gk) {
              const fk = `wfail:${m.token}:${m.wave}:${m.phone}`;
              const code = String(err.code || '');
              await env.RATE.put(`wferr:${m.token}:${m.wave}:${m.phone}`, code, { expirationTtl: 30 * 86400 }).catch(() => {});
              /* 18/10: 131048 / 130429 = the NUMBER hit Meta's cap (250 business-
                 initiated conversations per 24h on an unverified business), not
                 this guest. Counting it as an attempt killed guests who never got
                 a message. Reopen them without a strike, raise one cap marker
                 that holds every wave until Meta's health check clears, and
                 tell Slack once — not 200 times. */
              /* 02/11 audit: 131042 (payment/eligibility on the WABA) is the
                 account, not the guest — no strike either, hold like a cap */
              const capHit = code === '131048' || code === '130429' || code === '131042';
              /* 02/11 audit: a cap hit used to reopen the same guest without
                 limit — one phone was accepted 28 times in a day, 2,091 of
                 2,350 templates failed. Three cap-reopens per guest per stage
                 (rolling 3 days), then it stops and waits for a human. */
              const capN = capHit ? (parseInt(await env.RATE.get(`wcapn:${m.token}:${m.wave}:${m.phone}`).catch(() => '0') || '0', 10) || 0) + 1 : 0;
              if (capHit) await env.RATE.put(`wcapn:${m.token}:${m.wave}:${m.phone}`, String(capN), { expirationTtl: 3 * 86400 }).catch(() => {});
              if (capHit && capN > 3) {
                await env.RATE.put(`wdead:${m.token}:${m.wave}:${m.phone}`, code, { expirationTtl: 120 * 86400 }).catch(() => {});
                retry = ' · נחסם 3 פעמים בתקרה — נעצר, דורש טיפול ידני';
                continue;
              }
              if (capHit) {
                await env.RATE.delete(m.gk); await reopenEdMark(env, m);
                await env.RATE.delete(`gday:${m.phone}:${ilDate()}`).catch(() => {});
                await env.RATE.delete(`wave:${m.token}:${m.wave}`).catch(() => {});
                /* lifecycle sends close their event flag on "accepted"; reopen it too (01/11) */
                const lifeFlag = { daybefore: 'daybefore:', seating: 'seat:' }[m.wave];
                if (lifeFlag) await env.RATE.delete(lifeFlag + m.token).catch(() => {});
                await env.RATE.put('pacer:pending', ilDate(), { expirationTtl: 86400 }).catch(() => {});
                const pidHit = (await env.RATE.get('wamidpid:' + st.id).catch(() => null)) || '';
                const ids = guestPhoneIds(env);
                /* 02/11: hold the number with a growing backoff (10m → 20m → 40m … ≤ 6h); the
                   health check may not lift it before `wacapuntil` — Meta says AVAILABLE and then
                   rejects the very next burst with 131048 */
                if (pidHit) {
                  const nHits = (Number(await env.RATE.get('wacapn:' + pidHit).catch(() => 0)) || 0) + 1;
                  const backoff = Math.min(6 * 3600, 600 * Math.pow(2, nHits - 1));
                  await env.RATE.put('wacapn:' + pidHit, String(nHits), { expirationTtl: 24 * 3600 }).catch(() => {});
                  await env.RATE.put('wacapuntil:' + pidHit, String(Date.now() + backoff * 1000), { expirationTtl: backoff + 60 }).catch(() => {});
                  await env.RATE.put('wacap:' + pidHit, new Date().toISOString(), { expirationTtl: 24 * 3600 }).catch(() => {});
                }
                /* the global hold only when every number is capped (or there is just one) */
                const allHeld = ids.length <= 1 || (await Promise.all(ids.map(id => env.RATE.get('wacap:' + id).catch(() => null)))).every(Boolean);
                if (allHeld && !await env.RATE.get('wacap:guests')) {
                  await env.RATE.put('wacap:guests', new Date().toISOString(), { expirationTtl: 24 * 3600 });
                  await alert(env, 'תקרת וואטסאפ', (ids.length > 1 ? 'כל המספרים של שיר הגיעו' : 'המספר של שיר הגיע') + ' לתקרת 250 שיחות ל-24 שעות (' + code + ')', 'השליחות ממתינות אוטומטית ונמשכות ברגע שמטא משחררת. אף אורח לא נספר כניסיון.', { key: 'wacap:guests', sev: 'P1', action: 'לחכות לפתיחת התקרה (המערכת מודיעה כשנפתחה) או לאמת את העסק במטא' });
                } else if (!allHeld) {
                  await env.RATE.delete(m.gk).catch(() => {}); await reopenEdMark(env, m);   /* resend via another number next tick */
                  /* once per number per hour, not once per failed message (02/11: hundreds) */
                  if (!(await seenOnce(env, `capslack:${pidHit || '?'}:${new Date().toISOString().slice(0, 13)}`))) await slackPost(env, `⚠️ מספר ${pidHit || '?'} של שיר הגיע לתקרה (${code}); השליחה ממשיכה מהמספרים האחרים.`, { quiet: true, cls: 'info', key: 'cap_number:' + (pidHit || '?') }).catch(() => {});
                }
                retry = ' · תקרת שיחות של מטא — ימתין וישלח שוב כשתיפתח';
                continue;
              }
              /* 131026 = not on WhatsApp / blocked us: retrying cannot help, the phone call round is the way */
              /* 02/11 audit: for the one-day lifecycle messages (table, day-before,
                 event-day, postpone, resend) Meta's per-user marketing cap (131049),
                 the marketing experiment holdout (130472) and "stopped marketing"
                 (131050) fail identically on every retry the same day — three
                 retries ten minutes apart only spent three more budget slots.
                 Waves keep their own 131049 defer (sendWave). */
              /* 08/11 (Richard): the marketing thank-you was refused for this guest → queue the UTILITY twin, no retry of the same one */
              if (m.wave === 'toda' && TODA_FALLBACK_CODES.test(code)) {
                await env.RATE.put(`todafb:${m.token}:${m.phone}`, code, { expirationTtl: 5 * 86400 }).catch(() => {});
                await env.RATE.put('pacer:pending', ilDate(), { expirationTtl: 86400 }).catch(() => {});
                retry = ' · תודה שיווקית נחסמה — תישלח גרסת השירות';
                continue;
              }
              const lifecycle = !/^[123]$/.test(String(m.wave));
              const terminal = code === '131026' || (lifecycle && /^(131049|130472|131050)$/.test(code));
              const n = terminal ? 3 : (parseInt(await env.RATE.get(fk) || '0', 10) || 0) + 1;
              await env.RATE.put(fk, String(n), { expirationTtl: 7 * 86400 });
              if (n >= 3) {
                await env.RATE.put(`wdead:${m.token}:${m.wave}:${m.phone}`, String(err.code || ''), { expirationTtl: 120 * 86400 });
                retry = ` · ניסיון ${n}/3 — נעצר, דורש טיפול ידני`;
                await logRow(env, 'removals', { kind: 'מסירה נכשלה 3 פעמים', channel: 'ווצאפ (מטא)', phone: m.phone, token: String(m.token || '').slice(0, 8),
                  scope: 'גל ' + m.wave + ' של האירוע הזה', said: '', detail: `${err.code || ''} ${err.title || ''}`.trim() });
              } else {
                await env.RATE.delete(m.gk); await reopenEdMark(env, m);          // wsent: gone → next tick resends
                await env.RATE.delete(`gday:${m.phone}:${ilDate()}`).catch(() => {}); // the one-a-day guard must not block the retry of a message that never arrived
                await env.RATE.delete(`wave:${m.token}:${m.wave}`).catch(() => {}); // the wave is open again
                /* 27/09: the pacer only runs the engine while pacer:pending says
                   today — without this the reopened guests waited for tomorrow
                   (Gal's wave, 131053, sat 3 hours) */
                await env.RATE.put('pacer:pending', ilDate(), { expirationTtl: 86400 }).catch(() => {});
                retry = ` · ניסיון ${n}/3 — יישלח שוב בפעימה הבאה`;
              }
            }
            /* was this an abandoned-lead chase touch? Meta accepted it (a
               message id came back, the stamp advanced) and only failed a
               few seconds later — revert the stamp so the sequence does not
               believe it landed. 131042 (billing) specifically gets one
               retry in 30 minutes, then gives up on THIS stage for today —
               the next stage still fires on schedule. Anything else just
               un-stamps and the normal every-tick retry picks it back up. */
            if (m && m.leadPhone && m.stampField) {
              const lk = 'lead:' + m.leadPhone;
              let lrec = null;
              try { lrec = JSON.parse(await env.RATE.get(lk)); } catch {}
              if (lrec && lrec[m.stampField]) {
                delete lrec[m.stampField];
                delete lrec[m.stampField + 'd'];
                if (/131042/.test(String(err.code || ''))) {
                  const outcome = markRetryOrDefer(lrec, m.stampField, ilDate());
                  retry = ' · לא נמסרה ללקוח — הרצף לא התקדם, ' +
                    (outcome === 'defer' ? 'ניסיון שני נכשל, ינסה שוב רק בשלב הבא' : 'ינסה שוב בעוד 30 דקות');
                } else {
                  retry = ' · לא נמסרה ללקוח — הרצף לא התקדם, ינסה שוב בפעימה הבאה';
                }
                await env.RATE.put(lk, JSON.stringify(lrec), { expirationTtl: LEAD_TTL }).catch(() => {});
              }
            }
          } catch {}
          await logEvent(env, { area: 'ווצאפ', action: 'מטא לא הצליחה למסור הודעה', ok: false, review: true,

d_pacer.source:
async function runPacer(env, run = null, { part = 'all' } = {}) {
  if (!env.RATE) return { ok: false, why: 'no-kv' };
  /* 03/11 ops center kill switch: nothing below runs, not even the Slack flush */
  if (await isOff(env, 'd_pacer')) return { ok: true, skipped: 'off:d_pacer' };
  /* child runs in the ledger (one row per sub-step) when the caller passed a run */
  const step = (id, fn) => run ? run.child(id, fn) : fn();
  const today = ilDate();
  /* 04/11 incident: one tick took 60+ s (autoretry + engine + sub-events ≈ 40 s
     before the dial slice) and the runtime cut it off, so from 12:00 nothing
     after the sends ran — no calls, no Shabbat sends — until pushed by hand.
     The cron now runs three independent parts in parallel: 'main' (sends and
     housekeeping), 'subevents' and 'calls'. A slow part can no longer starve
     the others. part='all' (manual /api/pacer) keeps the old single pass. */
  /* 04/11: the סקירה plan precompute is its own job too (it used to sit last in the main pass and got cut off) */
  if (part === 'plan') {
    /* 09/11: the cron invocation cannot afford a send-board rebuild (116 s) + 31 past audit days — the plan then never
       lands and the board shows yesterday's picture. Reuse the cached board, 3 past days; the board refreshes on its own route. */
    try { const r = await step('plan_precompute', () => precomputePlans(env, opsDeps(), planFns(), { buildBoard: false, pastDayBudget: 3 })); return { ok: true, part, ms: r && r.ms }; }
    catch (e) { return { ok: false, part, why: String((e && e.message) || e) }; }
  }
  if (part === 'calls' || part === 'subevents') {
    if (isNoContactDay(today)) return { ok: true, skipped: 'no-contact-day' };
    if (await sendingPaused(env)) return { ok: true, paused: true };
    const out = { date: today, part };
    if (part === 'subevents') {
      if (sendWindowState().open) out.subevents = await step('subevent_continue', () => continueSubevents(env, subeventDeps())).catch(e => ({ ok: false, error: String((e && e.message) || e) }));
      else out.subevents = { skipped: 'window' };
      return out;
    }
    await pacerCalls(env, step, out);
    return out;
  }
  /* 04/11 Make burn: sheet writes that failed while Make was down, replayed oldest first.
     Before everything else (Shabbat and paused included): a write is not a message. */
  const outbox = await step('sheet_outbox', () => drainSheetQueue(env, sheetBatchPost, { cap: 25 })).catch(e => ({ ok: false, error: String((e && e.message) || e) }));
  if (isNoContactDay(today)) { const quiet = { ok: true, skipped: 'no-contact-day' }; await templateCheck(env, quiet); return quiet; }

  /* Phase 6: flush last night's queued Slack alerts once the 09:00 window
     opens. No new cron needed — the pacer already ticks every 10 minutes;
     this just needs to notice the hour crossed 9 and hasn't flushed yet
     today. Runs even while sending is paused — a paused system is exactly
     when Richard still wants to see what queued overnight. */
  const ilHour = Number(new Intl.DateTimeFormat('en-US', { timeZone: 'Asia/Jerusalem', hour: '2-digit', hour12: false }).format());
  if (ilHour >= 9 && await env.RATE.get('slackqflush:' + today) !== '1') {
    await env.RATE.put('slackqflush:' + today, '1', { expirationTtl: 2 * 86400 }).catch(() => {});
    /* 04/11 slack-gate: the 09:00 "בוקר · סיכום" (slack-gate.js slackDigest) replaces the bare night-queue
       flush — open conditions, what resolved overnight, the info lines, the night queue and today's plan,
       ONE message. Kill switch auto:off:slack_digest (registry node slack_digest) → the old flush runs
       instead so the night queue never piles up. */
    if (await isOff(env, 'slack_digest')) await flushSlackQueue(env).catch(() => {});
    else await step('slack_digest', () => slackDigest(env, { post: t => slackSend(env, t, { oneoff: true, urgent: true, digest: true }), plan: () => digestPlan(env) })).catch(() => {});   /* oneoff: the one daily digest */
  }
  /* ads health, once an hour inside Slack hours (the alert itself is
     urgent, so quiet hours are respected by not asking at night) */
  if (ilHour >= 9 && ilHour < 21) {
    const hk = 'adshealth:' + today + ':' + ilHour;
    if (await env.RATE.get(hk) !== '1') {
      await env.RATE.put(hk, '1', { expirationTtl: 2 * 86400 }).catch(() => {});
      await adsHealthAlert(env).catch(() => {});
    }
  }

  if (await sendingPaused(env)) return { ok: true, paused: true };

  const out = { date: today };
  if (outbox && !outbox.idle) out.sheet_outbox = { drained: outbox.drained || 0, left: outbox.left || 0, ok: !!outbox.ok };

  /* messages first: they are cheaper and they warm the 24h window a call
     lands in more gracefully than a cold ring does */
  const sendWin = sendWindowState();
  /* 22/10 Richard: guests whose invitation failed (130472/131049/131026, not
     yet 3 strikes) are retried automatically once per send day; before this
     it only happened when someone ran /api/wave-retry by hand. */
  /* 03/11: auto:off:autoretry skips it WITHOUT burning autoretry:<day>, so switching it back on the same day still runs it */
  if (sendWin.open && await isOff(env, 'autoretry')) out.autoretry = { skipped: 'off:autoretry' };
  else if (sendWin.open && !(await env.RATE.get('autoretry:' + today).catch(() => null))) {
    await env.RATE.put('autoretry:' + today, '1', { expirationTtl: 86400 }).catch(() => {});
    try {
      const raw = await snapshotCached(env, 'send').catch(() => null);
      /* 04/11: no (fresh) snapshot → nothing to retry against; un-burn the day so the next tick tries */
      if (!raw) { await env.RATE.delete('autoretry:' + today).catch(() => {}); throw new Error(snapMiss(env)); }
      const by = await undeliveredByEvent(env, raw);
      /* 12/11: accepted-but-never-delivered for 24 h → one more attempt (wsent dropped, wstale set) */
      const stale = await staleSentByEvent(env, raw, Date.now(), { mark: true }).catch(() => ({}));
      for (const [t, ev] of Object.entries(stale)) { (by[t] = by[t] || { name: ev.name, list: [] }).list.push(...ev.list); }
      let n = 0, evs = 0;
      for (const [token, ev] of Object.entries(by || {})) {
        const list = (ev.list || []).filter(g => !g.dead);
        if (!list.length) continue;
        evs++;
        const waves = new Set(list.map(g => g.wave));
        /* 02/11 decision D5 (integration default): 3 attempts per guest per wave
           for the wave's whole life — the daily retry reopens the guest but keeps
           the wfail:<…> strike count (it used to delete it: 3 a day, up to 9) */
        for (const g of list) { n++; for (const k of [`wferr:${token}:${g.wave}:${g.phone}`, `gday:${g.phone}:${today}`]) await env.RATE.delete(k).catch(() => {}); }
        for (const w of waves) await env.RATE.delete(`wave:${token}:${w}`).catch(() => {});
      }
      if (n) { await env.RATE.put('pacer:pending', today, { expirationTtl: 86400 }).catch(() => {}); await logEvent(env, { area: 'שליחה', action: `ניסיון חוזר אוטומטי: ${n} אורחים ב-${evs} אירועים`, ok: true }).catch(() => {}); }
      out.autoretry = { guests: n, events: evs };
    } catch (e) { out.autoretry = { error: String(e && e.message) }; }
  }
  if (sendWin.open && await env.RATE.get('pacer:pending') === today) {
    /* 12/11 Richard: how many this tick — what is still planned for today (plan:today, precomputed every tick)
       against the minutes left to 12:00 and to the window's close */
    const paceInfo = await (async () => {
      const base = paceSends(env, PACE_SENDS), max = paceSendsMax(env);
      try {
        const plan = JSON.parse((await env.RATE.get('plan:today')) || 'null');
        const days = plan && plan.data && plan.data.days; const d0 = Array.isArray(days) ? days.find(x => x.day === today) || days[0] : (days && days[today]);
        const items = (d0 && d0.items) || [];
        const remaining = items.filter(i => i.kind === 'send' && i.status !== 'done' && i.status !== 'missed').reduce((n, i) => n + Math.max(0, (Number(i.planned_n) || 0) - (Number(i.done_n) || 0)), 0);
        const il = new Intl.DateTimeFormat('en-US', { timeZone: 'Asia/Jerusalem', weekday: 'short', hour: '2-digit', minute: '2-digit', hour12: false }).formatToParts(new Date());
        const g = t => (il.find(x => x.type === t) || {}).value || ''; const mins = Number(g('hour')) % 24 * 60 + Number(g('minute'));
        const close = g('weekday') === 'Fri' ? 13 * 60 : 20 * 60 + 30, target = g('weekday') === 'Fri' ? 12 * 60 : 12 * 60;
        return { ...dynamicPace({ remaining, minsLeft: close - mins, minsToTarget: target - mins, base, max }), remaining, base, max };
      } catch (e) { return { pace: base, why: 'no-plan', base, max }; }
    })();
    if (env.RATE) await env.RATE.put('pacer:pace', JSON.stringify({ ...paceInfo, at: new Date().toISOString() }), { expirationTtl: 3600 }).catch(() => {});
    const r = await step('d_engine', () => runDailyEngine(env, false, null, { budget: paceInfo.pace })).catch(e => {
      return { ok: false, error: String((e && e.message) || e) };
    });
    out.sends = r && r.ok ? { ran: true, truncated: !!r.truncated, pace: paceInfo.pace, pace_why: paceInfo.why, remaining: paceInfo.remaining } : { ran: false, error: r && r.error, pace: paceInfo.pace };
    /* a tick that failed while work is pending used to vanish into the
       heartbeat; one alert a day is the difference between "Richard knows in
       20 minutes" and "somebody finds out at the hall" */
    if ((!r || !r.ok) && !(await env.RATE.get('paceralert:' + today))) {
      await env.RATE.put('paceralert:' + today, '1', { expirationTtl: 86400 });
      await slackPost(env, `🚨 *פעימת שליחה נכשלה* (${(r && r.error) || 'שגיאה'}) בזמן שיש עבודה ממתינה. הפעימה הבאה תנסה שוב בעוד 10 דקות; אם ההתראה הזאת חוזרת מחר — משהו תקוע באמת.`, { key: 'pacer_failed', sev: 'P1' });
    }
  } else {
    out.sends = { ran: false, why: sendWin.open ? 'nothing-pending' : sendWin.why };
  }

  /* 04/11: a sub-event Richard started ("שלח") keeps going by itself, one
     capped slice per tick, until everyone is sent → completed_at + Slack.
     Never starts one that was not started by hand. auto:off:subevent_continue. */
  if (part === 'all' && sendWin.open) out.subevents = await step('subevent_continue', () => continueSubevents(env, subeventDeps())).catch(e => ({ ok: false, error: String((e && e.message) || e) }));

  /* Chasing an abandoned lead does not need the sheet, only KV, so it runs on
     every tick rather than waiting for the nightly engine. Without this the
     "five hours later" promise was really "tomorrow morning", which for
     somebody who asked about their wedding this afternoon is a different
     product. Cheap: one KV list, no Make operation. */
  if (sendWin.open) {
    const chased = await step('lead_chase', () => chaseAbandonedLeads(env, false, { left: 10 })).catch(() => []);
    out.leads = chased.filter(c => c.sent).length;
  }

  /* then the dial slice (its own cron job since 04/11; inline only for part='all') */
  if (part === 'all') await pacerCalls(env, step, out);
  await step('template_check', async () => { await templateCheck(env, out); return out.tmplcheck || { ok: true }; }).catch(() => {});

  /* the journal rides the same tick: everything buffered since the last one
     lands in the sheet as a single Sheets call */
  try { out.journal = await flushEventLog(env); } catch (e) { out.journal = { ok: false, why: String(e && e.message) }; }
  try { out.sheetlogs = await flushSheetLogs(env); } catch (e) { out.sheetlogs = { ok: false, why: String(e && e.message) }; }
  try { out.invoices = await syncInvoices(env); } catch (e) { out.invoices = { ok: false, why: String(e && e.message) }; }

  /* the doctor: looks at what this tick produced, fixes what it can, and
     shouts once a day about what it cannot. Never throws into the pacer. */
  try { out.doctor = await step('doctor', () => runDoctor(env, out, sendWin, callWindowState())); }   /* 09/11: callWin moved to pacerCalls on 04/11 → ReferenceError every pacer run */ catch (e) { out.doctor = { ok: false, why: String(e && e.message) }; }

  /* a heartbeat worth having: "the pacer is alive" is otherwise invisible
     until the day somebody notices nothing went out */
  await env.RATE.put('pacer:last', JSON.stringify({ at: new Date().toISOString(), ...out }),
    { expirationTtl: 3 * 86400 }).catch(() => {});
  /* 04/11 "מתוכנן מול בוצע": today / week / month composed once per tick into KV plan:<period> (ops-plan.js), so the
     סקירה answers from KV instead of 49 s of live reads. Last on purpose: it never delays a send or a dial. */
  if (part === 'all') try {
    out.plan = await step('plan_precompute', async () => { const r = await precomputePlans(env, opsDeps(), planFns()); return { ok: r.ok, ms: r.ms, errors: r.errors, line: r.plans.today && r.plans.today.status ? r.plans.today.status.line_he : '' }; });
  } catch (e) { out.plan = { ok: false, why: String((e && e.message) || e) }; }
  return { ok: true, ...out };
}

d_engine.source:
async function runDailyEngine(env, dry, todayOverride, opts = {}) {
  /* how many guest messages this invocation may send before it stops and
     leaves the rest for the next tick. null = no ceiling (the nightly run). */
  /* 02/11 audit: the contact window was only enforced by the CALLERS (cron
     budget 0 before 09:00, pacer gate). A manual /api/daily-run without a
     budget at 22:00 sent every due wave + lifecycle message at night, and
     the client stages (report, wrap-up, nudges, upsell) had no window at all
     (automations-registry warning). Now: window closed → guest budget 0 and
     client templates wait; `force` (admin test) still overrides.
     `let`: the cap cut below (fitBatch) may replace a null budget. */
  const windowOpen = !!(dry || opts.force || sendWindowState().open);
  let budget = !windowOpen ? { left: 0 } : (opts.budget != null ? { left: Number(opts.budget) } : null);
  let clientWaiting = false;
  const sendClientE = async (...a) => {
    if (!windowOpen) { clientWaiting = true; return { ok: false, error: 'outside-hours', held: true }; }
    return sendClient(...a);
  };
  const raw = await readSnapshot(env, 'send');
  if (!raw) {
    await alert(env, 'מנוע יומי', 'אין גישה לנתוני הגיליון — הדוחות לא נשלחו', '', { key: 'engine_no_sheet', sev: 'P1' });
    return { ok: false, error: 'no-snapshot', why: snapMiss(env, 'no-snapshot') };
  }
  /* date override is allowed in dry runs only — for testing tomorrow safely */
  const today = (dry && /^\d{4}-\d{2}-\d{2}$/.test(String(todayOverride || '')))
    ? String(todayOverride) : ilDate();
  const isShabbat = new Date(today + 'T12:00:00Z').getUTCDay() === 6;
  /* force: admin-only, for a test run against the owner's own numbers when
     the calendar says no. Never reachable from a cron or the pacer. */
  if (isShabbat && !dry && !opts.force) return { ok: true, skipped: 'shabbat' };
  /* חג: no messages, no calls, no "friendly nudge". A holiday that nobody
     configured is the one day a wedding RSVP text is genuinely offensive. */
  if (isNoContactDay(today) && !dry && !opts.force) {
    if (env.RATE && !(await env.RATE.get('holnote:' + today))) {
      await env.RATE.put('holnote:' + today, '1', { expirationTtl: 3 * 86400 });
      await slackPost(env, `🕯️ *${today} מסומן כיום ללא יצירת קשר.* לא נשלחו הודעות ולא בוצעו שיחות. הכל ימשיך מחר.`, { quiet: true });
    }
    return { ok: true, date: today, skipped: 'no-contact-day' };
  }

  const evRows = (raw.events && raw.events.values) || [];
  const gRows = (raw.guests && raw.guests.values) || [];
  /* remember where each guest lives in the sheet (values start at A2), so a
     filtered subset can still write its send-stamp back to the right row */
  gRows.forEach((g, i) => { if (g && typeof g === 'object') g.__row = i + 2; });
  const out = [];

  /* the master switch: stop before a single message is composed */
  if (await sendingPaused(env)) {
    if (!dry) await slackPost(env, '⏸️ *המנוע היומי לא רץ* — השליחה מושהית ידנית. להפעלה מחדש: המתג במרכז הבקרה.', { key: 'engine_paused', sev: 'P1', action: 'להפעיל מחדש במתג במרכז הבקרה — ishur.io/ops.html#/control' });
    return { ok: true, date: today, paused: true, events: [] };
  }

  /* keep Meta's cap cached so the 80% alert has a number during the waves */
  await waCapInfo(env).catch(() => null);

  /* 02/11 (Richard): "never send a batch that will be refused because the cap
     is reached — if there's no room, don't send, queue." The tick's guest
     budget is cut to the room Meta still gives us BEFORE the first send; the
     waves stop at budget.left = 0 and keep their cursor, so the rest is
     simply the next tick's queue. */
  if (!dry && env.RATE) {
    const cap = await guestCapacity(env).catch(() => null);
    if (cap && cap.numbers.length) {
      const wanted = budget ? budget.left : cap.remaining;
      const fit = fitBatch(cap.remaining, wanted);
      if (budget) budget.left = fit.send; else budget = { left: fit.send };
      out.push({ type: 'cap', scope: cap.scope, limit: cap.limit, used: cap.used, remaining: cap.remaining, batch: wanted, send: fit.send, held: fit.held });
      if (fit.held > 0) {
        const hk = `capheld:${today}:${new Date().getUTCHours()}`;
        if (!(await env.RATE.get(hk).catch(() => null))) {
          await env.RATE.put(hk, '1', { expirationTtl: 2 * 3600 }).catch(() => {});
          await logEvent(env, { area: 'שליחה', action: 'held: cap — המנה קוצרה לפני שליחה', ok: true,
            detail: `נשארו ${cap.remaining} מתוך ${cap.limit} (${cap.scope}) · מנה ${wanted} → יוצאות ${fit.send}, בתור ${fit.held}` }).catch(() => {});
        }
      }
    }
  }

  /* ── stage 0.4: left a phone, never paid ────────────────────────────────
     Preview only. The live chase runs from the pacer every ten minutes; doing
     it here too meant the same scan ran twice per tick (review finding #1). */
  if (dry) for (const r of await chaseAbandonedLeads(env, true, budget)) out.push(r);

  /* ── stage 0.5: paid but never uploaded a guest list ──────────────────────
     handleGrowIpn drops pend:<token> at payment; a successful upload deletes
     it. Whatever is still pending a day later gets one friendly nudge with
     the personal link (ishur_tzikoret_kovetz) + a tagged Slack heads-up.   */
  if (env.RATE) {
    try {
      const pend = await kvPrefix(env, 'pend:');
      for (const [token, vRaw] of Object.entries(pend)) {
        let v = null; try { v = JSON.parse(vRaw); } catch {}
        if (!v || !v.phone) { if (!dry) await env.RATE.delete('pend:' + token); continue; }
        if (await env.RATE.get('uploaded:' + token)) { if (!dry) await env.RATE.delete('pend:' + token); continue; }
        const ageDays = Math.round((Date.parse(today) - Date.parse(String(v.at || today).slice(0, 10))) / 864e5);
        if (ageDays < 1) continue;
        if (dry) { out.push({ token, type: 'stuck_client', would_send_to: v.phone }); continue; }
        const first = (String(v.name || '').split(' ')[0] || '').trim() || 'לקוח יקר';
        const wa = await sendClientE(env, v.phone, 'ishur_tzikoret_kovetz',
          [first, 'https://ishur.io/upload.html?t=' + token], { token });
        if (wa.ok) {
          await addEvCost(env, token, msgCost('ishur_tzikoret_kovetz'));
          await slackPost(env, `🟠 *לקוח תקוע* · ${v.name || ''} ${v.phone}\nשילם אתמול ולא העלה רשימת מוזמנים. נשלחה תזכורת עם הקישור האישי. אפשר לענות לו מהאינבוקס, והוא גם יכול פשוט לשלוח את האקסל בוואטסאפ.`, { key: 'client_stuck:' + v.phone, action: 'לענות מהאינבוקס או לחכות לקובץ' });
          await env.RATE.delete('pend:' + token);
          await env.RATE.put('pend2:' + token, today, { expirationTtl: 30 * 86400 });
        }
        out.push({ token, type: 'stuck_client', sent: wa.ok });
      }
    } catch (e) { await alert(env, 'לקוח תקוע', 'שלב הבדיקה נפל', String(e && e.message), { key: 'client_stuck_check' }); }
  }

  /* ── stage 0.35: the package on the event row, from the payment ──────────
     Make writes AF/AG only when a lead row existed; a direct-link buyer's row
     has both empty → no upload cap, plan defaults to פרמיום. Fill them from
     paid:<token> once. The sheet stays editable by hand afterwards. */
  if (!dry && env.RATE && env.BRAIN_HOOK) {
    const fills = [];
    for (let i = 0; i < evRows.length; i++) {
      const ev = evRows[i]; if (!ev) continue;
      const token = String(ev[1] || '').trim();
      if (!token || String(ev[7] || '').trim() !== 'כן') continue;
      const planEmpty = !String(ev[31] || '').trim(), tierEmpty = !String(ev[32] || '').trim();
      /* J (invoice) is filled whenever it is empty and Morning has one — even
         after the plan/tier fill already ran (Richard 21/10: Shilat showed "חסרה") */
      if (!String(ev[9] || '').trim()) {
        try { const inv = JSON.parse((await env.RATE.get('invoice:' + token)) || 'null'); if (inv && inv.url) fills.push({ range: `אירועים!J${i + 2}`, values: [[inv.number ? `${inv.number} · ${inv.url}` : inv.url]] }); } catch {}
      }
      if (!planEmpty && !tierEmpty) continue;
      if (await env.RATE.get('planfill:' + token)) continue;
      let paid = null; try { paid = JSON.parse((await env.RATE.get('paid:' + token)) || 'null'); } catch {}
      if (!paid) continue;
      const row = i + 2;
      if (planEmpty && paid.planText) fills.push({ range: `אירועים!AF${row}`, values: [[paid.planText]] });
      try {
        const inv = JSON.parse((await env.RATE.get('invoice:' + token)) || 'null');
        if (inv && inv.url && !String(ev[9] || '').trim()) fills.push({ range: `אירועים!J${row}`, values: [[inv.number ? `${inv.number} · ${inv.url}` : inv.url]] });
      } catch {}
      if (tierEmpty && paid.tier) fills.push({ range: `אירועים!AG${row}`, values: [[String(paid.tier)]] });
      await env.RATE.put('planfill:' + token, today, { expirationTtl: 400 * 86400 });
      await logEvent(env, { area: 'תשלום', action: 'חבילה ומכסה נכתבו לשורת האירוע מהתשלום', ok: true, token,
        detail: `${paid.planText || ''} · ${paid.tier || '?'} מוזמנים · "${paid.desc || ''}"` });
      if (fills.length >= 20) break;
    }
    /* host roles that setup could not place because the row did not exist yet */
    for (let i = 0; i < evRows.length && fills.length < 20; i++) {
      const ev = evRows[i]; if (!ev) continue;
      const token = String(ev[1] || '').trim();
      if (!token || String(ev[HOST_ROLES_IDX] || '').trim()) continue;
      const parked = await env.RATE.get('hostroles:' + token);
      if (!parked || !hostRolesOk(parked)) continue;
      fills.push({ range: `אירועים!${HOST_ROLES_COL}${i + 2}`, values: [[parked]] });
      await env.RATE.delete('hostroles:' + token).catch(() => {});
    }
    if (fills.length) { const okw = await sheetBatchWrite(env, fills); if (!okw) await alert(env, 'חבילה', 'כתיבת חבילה/מכסה לשורת אירוע נכשלה', `${fills.length} תאים`, { key: 'sheet_write_plan' }); }
  }

  /* ── stage 0.4: every paid event's owner is on the clients list ──────────
     Once per token, after the event name exists: a new client gets a row, a
     returning one gets this event appended in H/I. Reads the tab, so a row
     Make or a human added by hand is respected. */
  if (!dry && env.RATE && env.BRAIN_HOOK) {
    let n = 0;
    for (const ev of evRows) {
      if (!ev) continue;
      const token = String(ev[1] || '').trim();
      if (!token || String(ev[7] || '').trim() !== 'כן') continue;
      if (await env.RATE.get('clientrow:' + token)) continue;
      const phone = normPhone(ev[3] || '');
      const cr = await upsertClientRow(env, { clientId: String(ev[0] || '').trim() || ('C-' + phone.slice(-9)), name: String(ev[2] || '').trim(), phone,
        taxId: '', token, eventName: String(ev[34] || ev[5] || '').trim() });
      if (cr.ok) {
        await env.RATE.put('clientrow:' + token, today, { expirationTtl: 400 * 86400 });
        await logEvent(env, { area: 'לקוחות', action: cr.added ? 'לקוח נוסף לרשימת הלקוחות' : 'אירוע קושר ללקוח ברשימת הלקוחות', ok: true, phone, token,
          detail: `${String(ev[2] || '').trim()} · ${String(ev[34] || '').trim()}${cr.unchanged ? ' · כבר היה' : ''}` });
      } else {
        await logEvent(env, { area: 'לקוחות', action: 'כתיבה לרשימת הלקוחות נכשלה', ok: false, review: true, phone, token, detail: JSON.stringify(cr) });
      }
      if (++n >= 10) break;
    }
  }

  /* ── stage 0.55: paid, uploaded, but the settings step was never finished ──
     No event date or no send dates means the engine has nothing to fire on,
     so the event would sit paid and silent forever. Nudge the client back to
     the page (it resumes at the settings step) and say so in Slack.        */
  for (const ev of evRows) {
    const token = String(ev[1] || '').trim();
    const paid = String(ev[7] || '').trim() === 'כן';
    const cancelled = String(ev[27] || '').trim() === 'כן';
    const fileUp = String(ev[43] || '').trim() === 'כן';
    const phone = String(ev[3] || '').trim();
    if (!token || !paid || cancelled || !fileUp || !phone) continue;
    const evDate = String(ev[6] || '').trim().slice(0, 10);
    const anySend = [39, 40, 41].some(c => /^\d{4}-\d{2}-\d{2}/.test(String(ev[c] || '').trim()));
    if (/^\d{4}-\d{2}-\d{2}$/.test(evDate) && anySend) continue; // properly set up
    if (env.RATE && await env.RATE.get('nosetup:' + token)) continue;
    if (dry) { out.push({ token, type: 'no_setup', would_send_to: phone }); continue; }
    const first = (String(ev[2] || '').split(' ')[0] || '').trim() || 'לקוח יקר';
    const wa = await sendClientE(env, phone, 'ishur_tzikoret_kovetz',
      [first, 'https://ishur.io/upload.html?t=' + token], { token });

stuck_client.source:
/* ── stage 0.5: paid but never uploaded a guest list ──────────────────────
   handleGrowIpn drops pend:<token> at payment; a successful upload deletes
   it. Whatever is still pending a day later gets one friendly nudge with
   the personal link (ishur_tzikoret_kovetz) + a tagged Slack heads-up.   */
if (env.RATE) {
  try {
    const pend = await kvPrefix(env, 'pend:');
    for (const [token, vRaw] of Object.entries(pend)) {
      let v = null; try { v = JSON.parse(vRaw); } catch {}
      if (!v || !v.phone) { if (!dry) await env.RATE.delete('pend:' + token); continue; }
      if (await env.RATE.get('uploaded:' + token)) { if (!dry) await env.RATE.delete('pend:' + token); continue; }
      const ageDays = Math.round((Date.parse(today) - Date.parse(String(v.at || today).slice(0, 10))) / 864e5);
      if (ageDays < 1) continue;
      if (dry) { out.push({ token, type: 'stuck_client', would_send_to: v.phone }); continue; }
      const first = (String(v.name || '').split(' ')[0] || '').trim() || 'לקוח יקר';
      const wa = await sendClientE(env, v.phone, 'ishur_tzikoret_kovetz',
        [first, 'https://ishur.io/upload.html?t=' + token], { token });
      if (wa.ok) {
        await addEvCost(env, token, msgCost('ishur_tzikoret_kovetz'));
        await slackPost(env, `🟠 *לקוח תקוע* · ${v.name || ''} ${v.phone}\nשילם אתמול ולא העלה רשימת מוזמנים. נשלחה תזכורת עם הקישור האישי. אפשר לענות לו מהאינבוקס, והוא גם יכול פשוט לשלוח את האקסל בוואטסאפ.`, { key: 'client_stuck:' + v.phone, action: 'לענות מהאינבוקס או לחכות לקובץ' });
        await env.RATE.delete('pend:' + token);
        await env.RATE.put('pend2:' + token, today, { expirationTtl: 30 * 86400 });
      }
      out.push({ token, type: 'stuck_client', sent: wa.ok });
    }
  } catch (e) { await alert(env, 'לקוח תקוע', 'שלב הבדיקה נפל', String(e && e.message), { key: 'client_stuck_check' }); }
}

/* ── stage 0.35: the package on the event row, from the payment ──────────
   Make writes AF/AG only when a lead row existed; a direct-link buyer's row
   has both empty → no upload cap, plan defaults to פרמיום. Fill them from
   paid:<token> once. The sheet stays editable by hand afterwards. */
if (!dry && env.RATE && env.BRAIN_HOOK) {
  const fills = [];
  for (let i = 0; i < evRows.length; i++) {
    const ev = evRows[i]; if (!ev) continue;
    const token = String(ev[1] || '').trim();
    if (!token || String(ev[7] || '').trim() !== 'כן') continue;
