async function runPacer(env, run = null, { part = 'all' } = {}) {
  if (!env.RATE) return { ok: false, why: 'no-kv' };
  /* 03/11 ops center kill switch: nothing below runs, not even the Slack flush */
  if (await isOff(env, 'd_pacer')) return { ok: true, skipped: 'off:d_pacer' };
  /* child runs in the ledger (one row per sub-step) when the caller passed a run */
  const step = (id, fn) => run ? run.child(id, fn) : fn();
  const today = ilDate();
  /* 04/11 incident: one tick took 60+ s (autoretry + engine + sub-events ≈ 40 s
     before the dial slice) and the runtime cut it off, so from 12:00 nothing
     after the sends ran — no calls, no Shabbat sends — until pushed by hand.
     The cron now runs three independent parts in parallel: 'main' (sends and
     housekeeping), 'subevents' and 'calls'. A slow part can no longer starve
     the others. part='all' (manual /api/pacer) keeps the old single pass. */
  /* 04/11: the סקירה plan precompute is its own job too (it used to sit last in the main pass and got cut off) */
  if (part === 'plan') {
    /* 09/11: the cron invocation cannot afford a send-board rebuild (116 s) + 31 past audit days — the plan then never
       lands and the board shows yesterday's picture. Reuse the cached board, 3 past days; the board refreshes on its own route. */
    try { const r = await step('plan_precompute', () => precomputePlans(env, opsDeps(), planFns(), { buildBoard: false, pastDayBudget: 3 })); return { ok: true, part, ms: r && r.ms }; }
    catch (e) { return { ok: false, part, why: String((e && e.message) || e) }; }
  }
  if (part === 'calls' || part === 'subevents') {
    if (isNoContactDay(today)) return { ok: true, skipped: 'no-contact-day' };
    if (await sendingPaused(env)) return { ok: true, paused: true };
    const out = { date: today, part };
    if (part === 'subevents') {
      if (sendWindowState().open) out.subevents = await step('subevent_continue', () => continueSubevents(env, subeventDeps())).catch(e => ({ ok: false, error: String((e && e.message) || e) }));
      else out.subevents = { skipped: 'window' };
      return out;
    }
    await pacerCalls(env, step, out);
    return out;
  }
  /* 04/11 Make burn: sheet writes that failed while Make was down, replayed oldest first.
     Before everything else (Shabbat and paused included): a write is not a message. */
  const outbox = await step('sheet_outbox', () => drainSheetQueue(env, sheetBatchPost, { cap: 25 })).catch(e => ({ ok: false, error: String((e && e.message) || e) }));
  if (isNoContactDay(today)) { const quiet = { ok: true, skipped: 'no-contact-day' }; await templateCheck(env, quiet); return quiet; }

  /* Phase 6: flush last night's queued Slack alerts once the 09:00 window
     opens. No new cron needed — the pacer already ticks every 10 minutes;
     this just needs to notice the hour crossed 9 and hasn't flushed yet
     today. Runs even while sending is paused — a paused system is exactly
     when Richard still wants to see what queued overnight. */
  const ilHour = Number(new Intl.DateTimeFormat('en-US', { timeZone: 'Asia/Jerusalem', hour: '2-digit', hour12: false }).format());
  if (ilHour >= 9 && await env.RATE.get('slackqflush:' + today) !== '1') {
    await env.RATE.put('slackqflush:' + today, '1', { expirationTtl: 2 * 86400 }).catch(() => {});
    /* 04/11 slack-gate: the 09:00 "בוקר · סיכום" (slack-gate.js slackDigest) replaces the bare night-queue
       flush — open conditions, what resolved overnight, the info lines, the night queue and today's plan,
       ONE message. Kill switch auto:off:slack_digest (registry node slack_digest) → the old flush runs
       instead so the night queue never piles up. */
    if (await isOff(env, 'slack_digest')) await flushSlackQueue(env).catch(() => {});
    else await step('slack_digest', () => slackDigest(env, { post: t => slackSend(env, t, { oneoff: true, urgent: true, digest: true }), plan: () => digestPlan(env) })).catch(() => {});   /* oneoff: the one daily digest */
  }
  /* ads health, once an hour inside Slack hours (the alert itself is
     urgent, so quiet hours are respected by not asking at night) */
  if (ilHour >= 9 && ilHour < 21) {
    const hk = 'adshealth:' + today + ':' + ilHour;
    if (await env.RATE.get(hk) !== '1') {
      await env.RATE.put(hk, '1', { expirationTtl: 2 * 86400 }).catch(() => {});
      await adsHealthAlert(env).catch(() => {});
    }
  }

  if (await sendingPaused(env)) return { ok: true, paused: true };

  const out = { date: today };
  if (outbox && !outbox.idle) out.sheet_outbox = { drained: outbox.drained || 0, left: outbox.left || 0, ok: !!outbox.ok };

  /* messages first: they are cheaper and they warm the 24h window a call
     lands in more gracefully than a cold ring does */
  const sendWin = sendWindowState();
  /* 22/10 Richard: guests whose invitation failed (130472/131049/131026, not
     yet 3 strikes) are retried automatically once per send day; before this
     it only happened when someone ran /api/wave-retry by hand. */
  /* 03/11: auto:off:autoretry skips it WITHOUT burning autoretry:<day>, so switching it back on the same day still runs it */
  if (sendWin.open && await isOff(env, 'autoretry')) out.autoretry = { skipped: 'off:autoretry' };
  else if (sendWin.open && !(await env.RATE.get('autoretry:' + today).catch(() => null))) {
    await env.RATE.put('autoretry:' + today, '1', { expirationTtl: 86400 }).catch(() => {});
    try {
      const raw = await snapshotCached(env, 'send').catch(() => null);
      /* 04/11: no (fresh) snapshot → nothing to retry against; un-burn the day so the next tick tries */
      if (!raw) { await env.RATE.delete('autoretry:' + today).catch(() => {}); throw new Error(snapMiss(env)); }
      const by = await undeliveredByEvent(env, raw);
      /* 12/11: accepted-but-never-delivered for 24 h → one more attempt (wsent dropped, wstale set) */
      const stale = await staleSentByEvent(env, raw, Date.now(), { mark: true }).catch(() => ({}));
      for (const [t, ev] of Object.entries(stale)) { (by[t] = by[t] || { name: ev.name, list: [] }).list.push(...ev.list); }
      let n = 0, evs = 0;
      for (const [token, ev] of Object.entries(by || {})) {
        const list = (ev.list || []).filter(g => !g.dead);
        if (!list.length) continue;
        evs++;
        const waves = new Set(list.map(g => g.wave));
        /* 02/11 decision D5 (integration default): 3 attempts per guest per wave
           for the wave's whole life — the daily retry reopens the guest but keeps
           the wfail:<…> strike count (it used to delete it: 3 a day, up to 9) */
        for (const g of list) { n++; for (const k of [`wferr:${token}:${g.wave}:${g.phone}`, `gday:${g.phone}:${today}`]) await env.RATE.delete(k).catch(() => {}); }
        for (const w of waves) await env.RATE.delete(`wave:${token}:${w}`).catch(() => {});
      }
      if (n) { await env.RATE.put('pacer:pending', today, { expirationTtl: 86400 }).catch(() => {}); await logEvent(env, { area: 'שליחה', action: `ניסיון חוזר אוטומטי: ${n} אורחים ב-${evs} אירועים`, ok: true }).catch(() => {}); }
      out.autoretry = { guests: n, events: evs };
    } catch (e) { out.autoretry = { error: String(e && e.message) }; }
  }
  if (sendWin.open && await env.RATE.get('pacer:pending') === today) {
    /* 12/11 Richard: how many this tick — what is still planned for today (plan:today, precomputed every tick)
       against the minutes left to 12:00 and to the window's close */
    const paceInfo = await (async () => {
      const base = paceSends(env, PACE_SENDS), max = paceSendsMax(env);
      try {
        const plan = JSON.parse((await env.RATE.get('plan:today')) || 'null');
        const days = plan && plan.data && plan.data.days; const d0 = Array.isArray(days) ? days.find(x => x.day === today) || days[0] : (days && days[today]);
        const items = (d0 && d0.items) || [];
        const remaining = items.filter(i => i.kind === 'send' && i.status !== 'done' && i.status !== 'missed').reduce((n, i) => n + Math.max(0, (Number(i.planned_n) || 0) - (Number(i.done_n) || 0)), 0);
        const il = new Intl.DateTimeFormat('en-US', { timeZone: 'Asia/Jerusalem', weekday: 'short', hour: '2-digit', minute: '2-digit', hour12: false }).formatToParts(new Date());
        const g = t => (il.find(x => x.type === t) || {}).value || ''; const mins = Number(g('hour')) % 24 * 60 + Number(g('minute'));
        const close = g('weekday') === 'Fri' ? 13 * 60 : 20 * 60 + 30, target = g('weekday') === 'Fri' ? 12 * 60 : 12 * 60;
        return { ...dynamicPace({ remaining, minsLeft: close - mins, minsToTarget: target - mins, base, max }), remaining, base, max };
      } catch (e) { return { pace: base, why: 'no-plan', base, max }; }
    })();
    if (env.RATE) await env.RATE.put('pacer:pace', JSON.stringify({ ...paceInfo, at: new Date().toISOString() }), { expirationTtl: 3600 }).catch(() => {});
    const r = await step('d_engine', () => runDailyEngine(env, false, null, { budget: paceInfo.pace })).catch(e => {
      return { ok: false, error: String((e && e.message) || e) };
    });
    out.sends = r && r.ok ? { ran: true, truncated: !!r.truncated, pace: paceInfo.pace, pace_why: paceInfo.why, remaining: paceInfo.remaining } : { ran: false, error: r && r.error, pace: paceInfo.pace };
    /* a tick that failed while work is pending used to vanish into the
       heartbeat; one alert a day is the difference between "Richard knows in
       20 minutes" and "somebody finds out at the hall" */
    if ((!r || !r.ok) && !(await env.RATE.get('paceralert:' + today))) {
      await env.RATE.put('paceralert:' + today, '1', { expirationTtl: 86400 });
      await slackPost(env, `🚨 *פעימת שליחה נכשלה* (${(r && r.error) || 'שגיאה'}) בזמן שיש עבודה ממתינה. הפעימה הבאה תנסה שוב בעוד 10 דקות; אם ההתראה הזאת חוזרת מחר — משהו תקוע באמת.`, { key: 'pacer_failed', sev: 'P1' });
    }
  } else {
    out.sends = { ran: false, why: sendWin.open ? 'nothing-pending' : sendWin.why };
  }

  /* 04/11: a sub-event Richard started ("שלח") keeps going by itself, one
     capped slice per tick, until everyone is sent → completed_at + Slack.
     Never starts one that was not started by hand. auto:off:subevent_continue. */
  if (part === 'all' && sendWin.open) out.subevents = await step('subevent_continue', () => continueSubevents(env, subeventDeps())).catch(e => ({ ok: false, error: String((e && e.message) || e) }));

  /* Chasing an abandoned lead does not need the sheet, only KV, so it runs on
     every tick rather than waiting for the nightly engine. Without this the
     "five hours later" promise was really "tomorrow morning", which for
     somebody who asked about their wedding this afternoon is a different
     product. Cheap: one KV list, no Make operation. */
  if (sendWin.open) {
    const chased = await step('lead_chase', () => chaseAbandonedLeads(env, false, { left: 10 })).catch(() => []);
    out.leads = chased.filter(c => c.sent).length;
  }

  /* then the dial slice (its own cron job since 04/11; inline only for part='all') */
  if (part === 'all') await pacerCalls(env, step, out);
  await step('template_check', async () => { await templateCheck(env, out); return out.tmplcheck || { ok: true }; }).catch(() => {});

  /* the journal rides the same tick: everything buffered since the last one
     lands in the sheet as a single Sheets call */
  try { out.journal = await flushEventLog(env); } catch (e) { out.journal = { ok: false, why: String(e && e.message) }; }
  try { out.sheetlogs = await flushSheetLogs(env); } catch (e) { out.sheetlogs = { ok: false, why: String(e && e.message) }; }
  try { out.invoices = await syncInvoices(env); } catch (e) { out.invoices = { ok: false, why: String(e && e.message) }; }

  /* the doctor: looks at what this tick produced, fixes what it can, and
     shouts once a day about what it cannot. Never throws into the pacer. */
  try { out.doctor = await step('doctor', () => runDoctor(env, out, sendWin, callWindowState())); }   /* 09/11: callWin moved to pacerCalls on 04/11 → ReferenceError every pacer run */ catch (e) { out.doctor = { ok: false, why: String(e && e.message) }; }

  /* a heartbeat worth having: "the pacer is alive" is otherwise invisible
     until the day somebody notices nothing went out */
  await env.RATE.put('pacer:last', JSON.stringify({ at: new Date().toISOString(), ...out }),
    { expirationTtl: 3 * 86400 }).catch(() => {});
  /* 04/11 "מתוכנן מול בוצע": today / week / month composed once per tick into KV plan:<period> (ops-plan.js), so the
     סקירה answers from KV instead of 49 s of live reads. Last on purpose: it never delays a send or a dial. */
  if (part === 'all') try {
    out.plan = await step('plan_precompute', async () => { const r = await precomputePlans(env, opsDeps(), planFns()); return { ok: r.ok, ms: r.ms, errors: r.errors, line: r.plans.today && r.plans.today.status ? r.plans.today.status.line_he : '' }; });
  } catch (e) { out.plan = { ok: false, why: String((e && e.message) || e) }; }
  return { ok: true, ...out };
}

lead_chase.source:
async function chaseAbandonedLeads(env, dry, budget) {
  if (!env.RATE) return [];
  const out = [];
  const now = Date.now();
  const today = ilDate();
  /* Two hard rules from the review (finding #1), learned the expensive way:
     1. A settled lead's lead: key DIES immediately — finished, bought, blocked,
        whatever. Skipping a dead lead still costs KV reads, and a fortnight of
        paid traffic builds enough of them that the scan alone blows the
        subrequest ceiling BEFORE the wave loop runs.
     2. The scan itself is bounded: one page, and skips also spend budget.
        Whatever does not fit this tick is ten minutes away from the next. */
  const page = await env.RATE.list({ prefix: 'lead:', limit: 1000 }).catch(() => null);
  if (!page) return out;

  const settle = async (phone, why) => {
    await env.RATE.put('leadchase:' + phone, why + ':' + new Date().toISOString(), { expirationTtl: LEAD_TTL });
    await env.RATE.delete('lead:' + phone);
  };
  const save = (phone, rec) =>
    env.RATE.put('lead:' + phone, JSON.stringify(rec), { expirationTtl: LEAD_TTL });

  /* a touch that Meta will refuse tomorrow too advances the sequence anyway:
     losing one text must not strand the person outside the call queue */
  const PERMANENT = /132000|132001|132005|131009|131026/;
  /* a touch that is refused for a reason that might clear on its own (Meta
     billing/eligibility, rate limits) must NOT advance the sequence — this
     branch covers Meta rejecting the send itself. It rarely does: 131042
     (billing) is typically ACCEPTED synchronously (a message id comes back,
     wa.ok is true) and only fails a few seconds later via the async delivery
     status webhook — the sequence advanced as if the touch landed while the
     lead got nothing (the real "every lead chase is silently failing",
     08/09). handleWaWebhook's status handler below is what actually reverts
     the stamp for that case, using the wamid: mapping written on send. */
  const TEMPORARY = /131042/;

  for (const k of page.keys) {
    if (budget && budget.left <= 0) break;
    const phone = k.name.slice('lead:'.length);
    let rec = null;
    try { rec = JSON.parse(await env.RATE.get(k.name)); } catch {}
    if (!rec) { await env.RATE.delete(k.name); continue; }
    if (await env.RATE.get('client:' + phone)) { await env.RATE.delete(k.name); continue; }
    if (await phoneBlocked(env, phone)) { if (!dry) await settle(phone, 'blocked'); continue; }
    /* answered = theirs now. Any inbound message after the form died means a
       human (or נועה) is already talking to them; more templates would nag.
       02/11: also a lead who wrote to US first on WhatsApp (Maya, Anat got
       "ראינו שהתחלתם להזמין … ולא סיימתם" 40 minutes after their own first
       message), and a chat a human took from the phone (human:/aioff:). */
    {
      let conv = null; try { conv = JSON.parse(await env.RATE.get('conv:' + phone)); } catch {}
      const human = (await env.RATE.get('human:' + phone).catch(() => null)) || (await env.RATE.get('aioff:' + phone).catch(() => null));
      const stop = chaseStopReason({ rec, conv, human });
      if (stop) { if (!dry) await settle(phone, stop === 'whatsapp-first' || stop === 'human' ? 'answered:' + stop : 'answered'); else out.push({ type: 'lead_stop', phone, why: stop }); continue; }
    }

    const first = (String(rec.name || '').split(' ')[0] || '').trim() || 'היי';
    const occ = cleanOccasion(rec.occasion) || 'אירוע שלכם';   /* 02/11 audit: the templates read "ל{{2}}" — "להאירוע שלכם" went out (live log) */
    const sendTouch = async (tmpl, stampField) => {
      if (budget) budget.left--;
      const wa = await sendClient(env, phone, tmpl, [first, occ]);
      if (wa.ok || PERMANENT.test(String(wa.error || ''))) {
        rec[stampField] = new Date().toISOString();
        rec[stampField + 'd'] = today;
        await save(phone, rec);
        /* accepted now, might still fail delivery a few seconds later — the
           status webhook needs to know which lead/stage this message id was
           to revert the stamp instead of leaving a false "sent" */
        if (wa.ok && wa.id && env.RATE) {
          await env.RATE.put('wamid:' + wa.id, JSON.stringify({ leadPhone: phone, stampField }),
            { expirationTtl: 3 * 86400 }).catch(() => {});
        }
      } else if (TEMPORARY.test(String(wa.error || ''))) {
        /* the rare synchronous-rejection case — the alert itself is
           rate-limited in the status handler / post(); one retry in 30
           minutes, then give up on this stage until the next one */
        markRetryOrDefer(rec, stampField, today);
        await save(phone, rec);
      }
      out.push({ type: 'lead_' + stampField, phone, sent: !!wa.ok, error: wa.error || '',
        deferred: !wa.ok && TEMPORARY.test(String(wa.error || '')) });
      return wa;
    };

    if (!rec.t1) {
      if (rec.t1defer === today) continue;
      if (rec.t1retryAt) { if (now < rec.t1retryAt) continue; }
      else if (now - Date.parse(rec.at || 0) < LEAD_T1_MS) continue;
      if (dry) { out.push({ type: 'lead_t1', phone, name: rec.name }); continue; }
      await sendTouch('ishur_lo_siyem', 't1');
      continue;
    }
    if (!rec.t2) {
      if (rec.t2defer === today) continue;
      if (rec.t2retryAt) { if (now < rec.t2retryAt) continue; }
      else if (today === rec.t1d || now - Date.parse(rec.t1) < LEAD_T2_MIN_MS) continue;
      if (dry) { out.push({ type: 'lead_t2', phone }); continue; }
      await sendTouch('ishur_lo_siyem_2', 't2');
      continue;
    }
    if (!rec.consent) {
      if (now - Date.parse(rec.t2) < LEAD_Q_MS) continue;
      if (dry) { out.push({ type: 'lead_queue', phone }); continue; }
      await env.RATE.put('lq:' + phone, JSON.stringify({ name: rec.name, occ, at: new Date().toISOString() }),
        { expirationTtl: 14 * 86400 });
      await settle(phone, 'queued');
      out.push({ type: 'lead_queue', phone, queued: true });
      continue;
    }
    if (!rec.t3) {
      if (rec.t3defer === today) continue;
      if (rec.t3retryAt) { if (now < rec.t3retryAt) continue; }
      else if (now - Date.parse(rec.t2) < LEAD_T3_MS) continue;
      if (dry) { out.push({ type: 'lead_t3', phone }); continue; }
      const wa3 = await sendTouch('ishur_lo_siyem_3', 't3');
      if (wa3.ok || PERMANENT.test(String(wa3.error || ''))) await settle(phone, 'done');
    }
  }
  const sentNow = out.filter(o => o.sent).length;
  const queuedNow = out.filter(o => o.queued).length;
  if (!dry && (sentNow || queuedNow)) {
    const bits = [];
    if (sentNow) bits.push(`${sentNow} הודעות המשך ללידים שנטשו`);
    if (queuedNow) bits.push(`${queuedNow} נכנסו לתור שיחות המכירה`);
    await slackPost(env, `📨 *${bits.join(' · ')}.*`, { quiet: true });
  }
  return out;
}

shir_callbacks.source:
async function runShirCallbacks(env, { max = 3, force = false } = {}) {
  if (await isOff(env, 'shir_callbacks')) return { dialed: 0, skipped: 'off:shir_callbacks' };
  if (!env.RETELL_KEY || !env.SHIR_FROM || !env.RATE) return { dialed: 0, why: 'not-configured' };
  if (await sendingPaused(env)) return { dialed: 0, why: 'paused' };
  const today = ilDate();
  if (isNoContactDay(today) && !force) return { dialed: 0, why: 'no-contact-day' };
  const win = callWindowState();
  if (!win.open && !force) return { dialed: 0, why: win.why };

  const raw0 = await kvPrefix(env, 'cbq:');
  const rows = [];
  for (const [phone, v] of Object.entries(raw0)) {
    let rec = null;
    try { rec = JSON.parse(v); } catch {}
    if (!rec) { await env.RATE.delete('cbq:' + phone).catch(() => {}); continue; }
    rows.push({ phone, ...rec });
  }
  rows.sort((a, b) => (Number(a.at) || 0) - (Number(b.at) || 0));

  const now = Date.now();
  const dialed = [];
  let waiting = 0, skipped = 0, snap;
  for (const r of rows) {
    if (dialed.length >= max) break;
    if (Number(r.tries) >= CBQ_MAX_TRIES) { await cbqClear(env, r.phone); skipped++; continue; }
    /* a call still in progress, or one that just ended and will clear itself */
    if (now - (Number(r.at) || 0) < CBQ_GRACE_MS && !force) { waiting++; continue; }
    if (Number(r.last) && now - Number(r.last) < CBQ_RETRY_MS && !force) { waiting++; continue; }
    if (await callBlocked(env, r.phone)) { await cbqClear(env, r.phone); skipped++; continue; }

    if (snap === undefined) snap = await snapshotCached(env, 'dial').catch(() => null);
    /* 04/11 Make burn: no snapshot (or one older than 15 min) → nobody knows if this is a guest or a
       client, and the wrong number would ring them. The entry stays queued for the next tick. */
    if (!snap) return { dialed: dialed.length, phones: dialed, queued: rows.length, waiting, skipped, why: snapMiss(env) };
    /* looked up fresh rather than replayed from the queue entry: between the
       missed call and the ring back, the guest may have answered on WhatsApp */
    const hit = snap ? inboundLookup(snap, r.phone, today, { prefer: r.why === 'guest-rang-noa' || r.why === 'noa-ring' ? 'client' : 'guest' })
      : { caller_kind: 'unknown', phone: r.phone, name: '' };
    const meta = inboundMetadata(hit, { callback: true });
    const target = {
      kind: 'callback', phone: r.phone, hit,
      guest_id: meta.guest_id || '', token: meta.token || '',
      tries: meta.tries || '0', max_tries: meta.max_tries || '3',
    };
    /* Separation rule: a guest is rung back by Shir from her number; a
       client, a lead or a stranger is rung back by Noa from hers. Never the
       other way round. Without Noa's line configured the entry waits. */
    const noaLine = hit.caller_kind !== 'guest';
    if (isTestPhone(env, target)) { await logEvent(env, { area: 'שיחות', action: 'חזרה למספר בדיקה דולגה', ok: true, phone: target, detail: 'why:test-number' }).catch(() => {}); continue; }
    if (noaLine && !(env.NOA_FROM && env.NOA_INBOUND_AGENT)) { waiting++; continue; }
    const payload = buildCallPayload(target, noaLine ? env.NOA_FROM : env.SHIR_FROM,
      { override_agent_id: noaLine ? env.NOA_INBOUND_AGENT : (env.SHIR_INBOUND_AGENT || '') });
    if (noaLine) {
      payload.metadata.line = 'noa';
      payload.retell_llm_dynamic_variables = noaInboundVariables(hit);
      payload.retell_llm_dynamic_variables.opening_line = openingLine(hit, { callback: true, noa: true });
    }
    const res = await fetch('https://api.retellai.com/v2/create-phone-call', {
      method: 'POST',
      headers: { Authorization: 'Bearer ' + env.RETELL_KEY, 'Content-Type': 'application/json' },
      body: JSON.stringify(payload),
    }).catch(() => null);
    await retellBillingGuard(env, res);
    if (res && (res.status === 200 || res.status === 201)) {
      let cid = ''; try { cid = String(((await res.clone().json()) || {}).call_id || ''); } catch {}
      await logRow(env, 'calls', { agent: noaLine ? 'נועה' : 'שיר', dir: 'יוצאת (חזרה)', phone: r.phone, name: (hit && hit.name) || '', kind: noaLine ? `חזרה ללקוח/ליד (${hit.caller_kind})` : 'חזרה למי שהתקשר',
        token: String((target && target.token) || '').slice(0, 8), status: 'חויג ' + ilTime(), id: cid });
      dialed.push(r.phone);
      /* the guest dialler keys its once-a-day rule on shirtry:<guest>:<day>;
         a ring-back that skipped it let the same guest be dialled twice in
         one day (review finding #11) */
      if (target.guest_id) {
        await env.RATE.put(`shirtry:${target.guest_id}:${today}`, '1', { expirationTtl: 2 * 86400 }).catch(() => {});
      }
      await env.RATE.put('cbq:' + r.phone,
        JSON.stringify({ ...r, phone: undefined, tries: (Number(r.tries) || 0) + 1, last: now }),
        { expirationTtl: CBQ_TTL_S });
    }
  }
  if (dialed.length) {
    await slackPost(env, `📲 שיר חזרה ל-${dialed.length} מי שהתקשרו אלינו ולא ענינו.`, { quiet: true });
  }
  return { dialed: dialed.length, phones: dialed, queued: rows.length, waiting, skipped };
}

shir_dispatch.source:
async function runShirDispatch(env, { max = 25, force = false, quiet = false } = {}) {
  if (await isOff(env, 'shir_dispatch')) return { ok: true, dialed: 0, skipped: 'off:shir_dispatch' };
  if (!env.RETELL_KEY || !env.SHIR_FROM) return { ok: false, why: 'not-configured' };
  if (await sendingPaused(env)) return { ok: true, dialed: 0, paused: true };
  /* a holiday is not a closed window, it is a closed day */
  if (isNoContactDay(ilDate()) && !force) return { ok: true, dialed: 0, closed: 'no-contact-day' };
  const win = callWindowState();
  /* the pacer calls this 63 times a day — the 60s cache exists exactly so
     those ticks do not each cost a Make operation (review finding #10) */
  const raw = await snapshotCached(env, 'dial').catch(() => null);
  if (!raw) return { ok: false, why: snapMiss(env) };
  const { queue } = buildCallQueue(raw, 3, await callsAddonTokens(env));
  /* a closed window with people waiting is worth saying out loud: silence here
     is exactly how the queue grew unnoticed */
  if (!win.open && !force) {
    if (queue.length && !quiet) {
      await slackPost(env, `🕐 ${queue.length} אורחים ממתינים לשיחה, אבל חלון החיוג סגור (${win.why}). ננסה בהזדמנות הבאה.`, { quiet: true });
    }
    return { ok: true, dialed: 0, closed: win.why, queued: queue.length };
  }
  const day = ilDate();
  /* 08/11: 37 of 94 calls on 04/11 died at the carrier (telephony_provider_permission_denied) — the
     dispatcher fired 25 calls at once every tick and ~12 of each burst were refused. Never start more
     than CALL_PARALLEL (default 10) at a time, minus the calls already live at Retell. */
  const parallel = Math.max(1, Math.min(25, Number(env.CALL_PARALLEL) || 10));
  let live = 0;
  try {
    const cr = await fetch('https://api.retellai.com/get-concurrency', { headers: { Authorization: 'Bearer ' + env.RETELL_KEY } });
    const cj = cr.ok ? await cr.json() : null; live = Number(cj && cj.current_concurrency) || 0;
  } catch {}
  const cap = Math.max(0, Math.min(Number(max) || 25, 25, parallel - live));
  if (!cap) return { ok: true, dialed: 0, busy: live, queued: queue.length };
  const dialed = [];
  let blocked = 0;
  for (const g of queue) {
    if (dialed.length >= cap) break;
    if (!shouldDial(g, day)) continue;
    if (env.RATE && await env.RATE.get('hold:' + g.token)) { blocked++; continue; }
    /* 03/11 ops call center: a round stopped for this event (POST /api/ops/call-round action stop) */
    if (env.RATE && await env.RATE.get('callstop:' + g.token)) { blocked++; continue; }
    /* was phoneBlocked() — which counts an opt-out. An opt-out is about
       messages, never about calls. See the note on callBlocked. */
    if (await callBlocked(env, g.phone)) { blocked++; continue; }
    if (await wrongNum(env, g.token, g.phone)) { blocked++; continue; }
    const dayKey = `shirtry:${g.guest_id}:${day}`;
    if (await env.RATE.get(dayKey)) continue;
    /* 08/11: one new call at a time, ~1.5 s apart — the carrier also refuses bursts per second */
    if (dialed.length) await new Promise(res => setTimeout(res, Number(env.CALL_GAP_MS) || 1500));
    const r = await fetch('https://api.retellai.com/v2/create-phone-call', {
      method: 'POST',
      headers: { 'Authorization': 'Bearer ' + env.RETELL_KEY, 'Content-Type': 'application/json' },
      /* 02/11 noa-chase R8: Shir's own lessons ({{memory}}) when the feature is on */
      body: JSON.stringify(buildCallPayload(g, env.SHIR_FROM, { memory: String(env.CALL_QA || 'on') !== 'off' ? await memoryBlock(env, 'שיר').catch(() => '') : '' })),
    }).catch(() => null);
    await retellBillingGuard(env, r);
    if (r && (r.status === 200 || r.status === 201)) {
      let cid = ''; try { cid = String(((await r.clone().json()) || {}).call_id || ''); } catch {}
      await logRow(env, 'calls', { agent: 'שיר', dir: 'יוצאת', phone: g.phone, name: g.name || '', kind: 'אורח (אישור הגעה)',
        token: String(g.token || '').slice(0, 8), status: 'חויג ' + ilTime(), id: cid, outcome: `ניסיון ${(Number(g.tries) || 0) + 1}/${g.max_tries || 3}` });
      await env.RATE.put(dayKey, '1', { expirationTtl: 2 * 86400 });
      await env.RATE.put('dialed:' + g.guest_id, day, { expirationTtl: 120 * 86400 });
      await env.RATE.put('calldate:' + g.token, day, { expirationTtl: 60 * 86400 });
      /* 04/11 brain call_round_not_dialing: when did this event last get a dial */
      await env.RATE.put('calllast:' + g.token, new Date().toISOString(), { expirationTtl: 30 * 86400 }).catch(() => {});
      dialed.push(g.guest_id);
    }
  }
  /* a queue that never empties is a silent failure: say so */
  if (queue.length && !dialed.length && !blocked && !quiet) {
    await slackPost(env, `📞 *${queue.length} אורחים ממתינים לשיחה ואף אחד לא חויג.* שווה בדיקה.`, { key: 'call_queue_stuck', level: queue.length, bands: [1, 10, 25, 50], sev: 'P1', action: 'לבדוק את Retell/Telnyx ואת חלון החיוג — ishur.io/ops.html#/calls' });
  } else if (dialed.length && !quiet) {
    await slackPost(env, `📞 שיר חייגה ל-${dialed.length} אורחים${blocked ? ` (${blocked} דולגו: מוקפא או חסום)` : ''}. בתור: ${queue.length}`, { quiet: true });
  }
  if (dialed.length) await logEvent(env, { area: 'שיחות', action: 'שיר חייגה (סבב)', ok: true,
    detail: `${dialed.length} חיוגים · בתור ${queue.length} · דולגו ${blocked}` });
  if (dialed.length && quiet && env.RATE) {
    /* one running total a day instead of a line every ten minutes */
    const dk = 'dialday:' + day;
    const n = (parseInt(await env.RATE.get(dk) || '0', 10) || 0) + dialed.length;
    await env.RATE.put(dk, String(n), { expirationTtl: 3 * 86400 });
  }
  return { ok: true, dialed: dialed.length, guests: dialed, queued: queue.length, blocked };
}

noa_lead_dial.source:
async function runShirLeadDial(env, { max = 3 } = {}) {
  const ready = String(env.NOA_LEADS || '') === 'on' && !!env.NOA_AGENT && !!env.NOA_FROM;
  if (!ready) return { dialed: 0, skipped: 'lead-calling-disabled' };
  /* Every guard the guest dialler obeys applies here too, and one more:
     a lead who already paid is a client, not a prospect. */
  if (!env.RETELL_KEY || !env.RATE) return { dialed: 0, skipped: 'not-configured' };
  if (await sendingPaused(env)) return { dialed: 0, skipped: 'paused' };
  const today = ilDate();
  if (isNoContactDay(today)) return { dialed: 0, skipped: 'no-contact-day' };
  if (!callWindowState().open) return { dialed: 0, skipped: 'window' };

  const snap = await snapshotCached(env, 'dial').catch(() => null);
  const rows = (snap && snap.leads && snap.leads.values) || [];
  const queued = await kvPrefix(env, 'lq:');
  const dialed = [];
  for (const phone of Object.keys(queued)) {
    if (dialed.length >= max) break;
    if (await callBlocked(env, phone)) { await env.RATE.delete('lq:' + phone).catch(() => {}); continue; }
    let q = null; try { q = JSON.parse(queued[phone]); } catch {}
    /* Phase 4: a requested call waits for ITS scheduled time, not just the
       next pacer tick — "מחר 11:00" must not ring the moment the pacer
       happens to run. Existing abandoned-lead entries stamp `at` as "now"
       at queue time, so this is always past for them — no behavior change. */
    if (q && q.at && Date.parse(q.at) > Date.now()) continue;
    /* answered on WhatsApp after joining the queue = נועה already has the
       conversation in text. Ringing them on top of it reads as pressure. */
    if (q && q.at && await leadReplied(env, phone, q.at)) {
      await env.RATE.delete('lq:' + phone).catch(() => {});
      continue;
    }
    let lead;
    if (q && q.requested) {
      /* came from a WhatsApp "call me" request, not the abandoned-lead
         sheet — a client asking for a call is not necessarily on that
         sheet at all, so build the call straight from what was said */
      lead = { kind: 'lead', phone, name: q.name || '', occasion: q.occ || 'אירוע', requested: true };
    } else {
      const row = rows.find(r => normPhone(r && r[2]) === phone);
      if (row) {
        lead = leadFromRow(row);
        if (lead.paid) { await env.RATE.delete('lq:' + phone).catch(() => {}); continue; }
      } else if (q && q.name) {
        /* no sheet row, but the queue entry carries enough to still make
           the call with the real abandoned-cart pitch (requested: false/
           absent) rather than dropping it — same reasoning as the
           requested:true branch above, just for the other opening line */
        lead = { kind: 'lead', phone, name: q.name, occasion: q.occ || 'אירוע', requested: false };
      } else {
        await env.RATE.delete('lq:' + phone).catch(() => {});
        continue;
      }
    }
    if (isTestPhone(env, phone)) { await env.RATE.delete('lq:' + phone).catch(() => {}); await logEvent(env, { area: 'שיחות', action: 'חיוג לליד במספר בדיקה דולג', ok: true, phone, detail: 'why:test-number' }).catch(() => {}); continue; }
    const res = await fetch('https://api.retellai.com/v2/create-phone-call', {
      method: 'POST',
      headers: { Authorization: 'Bearer ' + env.RETELL_KEY, 'Content-Type': 'application/json' },
      body: JSON.stringify(buildCallPayload(lead, env.NOA_FROM,
        /* 02/11 noa-chase R8: {{memory}} rides on every Noa call when the feature is on */
        { override_agent_id: env.NOA_AGENT, memory: String(env.NOA_CHASE || '') === 'on' ? await memoryBlock(env, 'נועה').catch(() => '') : '' })),
    }).catch(() => null);
    await retellBillingGuard(env, res);
    if (res && (res.status === 200 || res.status === 201)) {
      let cid = ''; try { cid = String(((await res.clone().json()) || {}).call_id || ''); } catch {}
      await logRow(env, 'calls', { agent: 'נועה', dir: 'יוצאת', phone, name: lead.name || '', kind: lead.requested ? 'ליד (ביקש שיחה)' : 'ליד (מכירה)', status: 'חויג ' + ilTime(), id: cid });
      dialed.push(phone);
      await env.RATE.delete('lq:' + phone).catch(() => {});
      /* one sales call per lead, ever — a no-answer does not earn a redial */
      await env.RATE.put('lqdone:' + phone, new Date().toISOString(), { expirationTtl: 90 * 86400 }).catch(() => {});
    }
  }
  if (dialed.length) {
    await slackPost(env, `📞 *נועה יצאה ל-${dialed.length} שיחות מכירה* ללידים שנטשו ולא ענו להודעות.`, { oneoff: true });   /* oneoff: one dial batch went out */
  }
  return { dialed: dialed.length, phones: dialed };
}

reconcile_calls.source:
async function reconcileShirCalls(env, { limit = 40, force = false } = {}) {
  if (!env.RETELL_KEY || !env.RATE) return { ok: false, why: 'not-configured' };
  const calls = (await retellListCalls(env, { sort_order: 'descending', limit })) || [];
  let applied = 0, skipped = 0;
  for (const c of calls) {
    const meta = (c && c.metadata) || {};
    if (!c || c.call_status !== 'ended' || !c.call_analysis || !meta.guest_id) { skipped++; continue; }
    /* inbound / callback / lead calls keep their own webhook-only handling */
    if (meta.kind && meta.kind !== 'guest') { skipped++; continue; }
    if (force) await env.RATE.delete('shirdone:end:' + c.call_id).catch(() => {});
    else if (await env.RATE.get('shirdone:end:' + c.call_id)) { skipped++; continue; }
    /* older than 3 days: the markers would have expired anyway, leave it */
    if (c.end_timestamp && Date.now() - Number(c.end_timestamp) > 3 * 86400e3) { skipped++; continue; }
    try {
      await processRetellEvent(env, { event: 'call_analyzed', call: c });
      applied++;
      await logEvent(env, { area: 'שיחות', action: 'תוצאת שיחה נקלטה מרטל (השלמה, בלי וובהוק)', ok: true,
        phone: String(c.to_number || '').replace('+', ''), token: String(meta.token || '').slice(0, 8), ref: String(c.call_id || '').slice(-12),
        detail: String(((c.call_analysis || {}).custom_analysis_data || {}).outcome || c.disconnection_reason || '') }).catch(() => {});
    } catch (e) {
      await logEvent(env, { area: 'שיחות', action: 'השלמת תוצאת שיחה נכשלה', ok: false, review: true, ref: String(c.call_id || '').slice(-12), detail: String(e && e.message).slice(0, 160) }).catch(() => {});
    }
  }
  return { ok: true, applied, skipped, seen: calls.length };
}

template_check.source:
async function templateCheck(env, out) {
  /* 08/11: the template guard, once an hour (own key) */
  try {
    const gk = 'tmplguard:hour:' + new Date().toISOString().slice(0, 13);
    if (env.RATE && !(await env.RATE.get(gk))) { await env.RATE.put(gk, '1', { expirationTtl: 7200 }); out.tmplguard = await runTemplateGuard(env); out.billing = await checkBillingRecovered(env).catch(e => ({ error: String(e && e.message || e) })); }
  } catch (e) { await alert(env, 'מטא', 'בודק התבניות נפל', String((e && e.message) || e), { key: 'tmplguard_crash', sev: 'P1' }).catch(() => {}); }
  /* Meta approvals, checked once an hour: the image invitation and the invoice
     template switch themselves on the moment they are approved. */
  try {
    const hourKey = 'tmplcheck:' + new Date().toISOString().slice(0, 13);
    if (env.WA_TOKEN && !(await env.RATE.get(hourKey))) {
      await env.RATE.put(hourKey, '1', { expirationTtl: 7200 });
      /* Each template is checked on the WABA that will actually SEND it. The
         invitation with the image header goes to guests, so it must be approved
         on Shir's account (1378764257421712) — approval on the 4499 account
         flipped the switch on 06/09 and every guest send died with 132001. The
         invoice goes to clients from 4499. */
      const checks = [
        { name: clientOnPortfolio(env) ? 'ishur_heshbonit_n' : 'ishur_heshbonit', key: 'invoicetmpl', waba: clientWaba(env), tok: clientToken(env) },
        /* 27/09: the _u copies are UTILITY (no per-user marketing cap, 131049); once approved they win the key */
        { name: 'hazmana_ishur_img_u', key: 'invitetmpl_img', waba: '1378764257421712', tok: env.WA_TOKEN_GUESTS },
        { name: 'hazmana_ishur_vid_u', key: 'invitetmpl_vid', waba: '1378764257421712', tok: env.WA_TOKEN_GUESTS },
        { name: 'hazmana_ishur_img', key: 'invitetmpl_img', waba: '1378764257421712', tok: env.WA_TOKEN_GUESTS, fallbackOnly: true },
        { name: 'hazmana_ishur_vid', key: 'invitetmpl_vid', waba: '1378764257421712', tok: env.WA_TOKEN_GUESTS, fallbackOnly: true },
        /* 25/10 Richard ("החלף"): the nav copy is billed MARKETING (₪0.12); the plain
           ishur_yom_lifnei is UTILITY (₪0.02). navtmpl stays unset on purpose. */
        /* 12/11: day-before twins with the invitation image → tmplimg:<base> = <base>_img once approved */
        ...['ishur_yom_lifnei', ...['t', 'g', 'gb', 'gp', 'tg', 'tgb', 'tgp'].map(k => 'ishur_lifnei_plain_' + k), ...['n', 't', 'g', 'gb', 'gp', 'tg', 'tgb', 'tgp'].map(k => 'ishur_lifnei_combo_' + k)]
          .map(n => ({ name: n + '_img', key: 'tmplimg:' + n, waba: '1378764257421712', tok: env.WA_TOKEN_GUESTS })),
        /* footer copies (11/09): approved → tmplf:<original> = <copy> */
        ...['ishur_toda_orach', 'ishur_dchiya', 'ishur_bitul', 'ishur_shulchan', 'ishur_yom_lifnei', 'ishur_hazmana_shuv']
          .map(n => ({ name: n + '_f', key: 'tmplf:' + n, waba: '1378764257421712', tok: env.WA_TOKEN_GUESTS })),
        ...(clientOnPortfolio(env) ? [] : ['ishur_syum_v3', 'ishur_doch', 'ishur_tzikoret_kovetz', 'ishur_tashlum', 'ishur_shidrug', 'ishur_shidrug_sichot']
          .map(n => ({ name: n + '_f', key: 'tmplf:' + n, waba: clientWaba(env), tok: clientToken(env) }))),
        /* live templates: watched for PAUSED / DISABLED / REJECTED only */
        ...['hazmana_ishur_v2', 'hazmana_ishur', 'ishur_toda_orach', 'ishur_dchiya', 'ishur_bitul', 'ishur_shulchan', 'ishur_yom_lifnei', 'ishur_hazmana_shuv']
          .map(n => ({ name: n, key: 'tmpllive:' + n, waba: '1378764257421712', tok: env.WA_TOKEN_GUESTS })),
        ...(clientOnPortfolio(env)
          ? ['ishur_syum_v3', 'ishur_kod', 'ishur_doch_n', 'ishur_tzikoret_kovetz_n', 'ishur_tashlum_n', 'ishur_heshbonit_n', 'ishur_lo_siyem_n', 'ishur_lo_siyem_2_n', 'ishur_lo_siyem_3_n', 'ishur_shidrug_n', 'ishur_shidrug_sichot_n']
          : ['ishur_syum_v3', 'ishur_doch', 'ishur_tzikoret_kovetz', 'ishur_tashlum', 'ishur_heshbonit', 'ishur_kod', 'ishur_lo_siyem_2', 'ishur_lo_siyem_3'])
          .map(n => ({ name: n, key: 'tmpllive:' + n, waba: clientWaba(env), tok: clientToken(env) })),
      ];
      for (const c of checks) {
        if (!c.tok) continue;
        const r = await fetch(`https://graph.facebook.com/v21.0/${c.waba}/message_templates?name=${c.name}&fields=name,status,rejected_reason,quality_score`,
          { headers: { Authorization: 'Bearer ' + c.tok } }).catch(() => null);
        const j = r ? await r.json().catch(() => null) : null;
        const t = ((j && j.data) || []).find(x => x.name === c.name);
        const key = t ? c.key : null;
        /* a UTILITY copy approved → it takes the key even if the marketing original holds it */
        if (key && t.status === 'APPROVED' && /_u$/.test(t.name) && (await env.RATE.get(key)) !== t.name) {
          await env.RATE.put(key, t.name);
          await logEvent(env, { area: 'מטא', action: `תבנית ${t.name} (UTILITY) אושרה — מחליפה את הגרסה השיווקית`, ok: true, ref: t.name });
          await slackPost(env, `✅ מטא אישרה את *${t.name}* כ-UTILITY — ההזמנות עוברות אליה (בלי מגבלת הודעות שיווקיות).`, { cls: 'info', key: 'template_ok:' + t.name });
        } else if (key && t.status === 'APPROVED' && !c.fallbackOnly && !(await env.RATE.get(key))) {
          await env.RATE.put(key, t.name);
          await logEvent(env, { area: 'מטא', action: `תבנית ${t.name} אושרה — הופעלה אוטומטית`, ok: true, ref: t.name });
          await slackPost(env, `✅ מטא אישרה את התבנית *${t.name}* — הופעלה אוטומטית.`, { cls: 'info', key: 'template_ok:' + t.name });
        }
        /* Richard, 11/09: any problem with a template → urgent Slack, and the
           system steps back to the previous template on its own so no send
           dies on it. Told once per template per status. */
        if (t && t.status !== 'APPROVED' && t.status !== 'PENDING' && t.status !== 'IN_APPEAL') {
          const seenKey = 'tmplbad:' + t.name + ':' + t.status;
          if (!(await env.RATE.get(seenKey))) {
            await env.RATE.put(seenKey, new Date().toISOString(), { expirationTtl: 30 * 86400 });
            const live = await env.RATE.get(key);
            if (live === t.name) { await env.RATE.delete(key); }
            const reason = (t.rejected_reason && t.rejected_reason !== 'NONE') ? t.rejected_reason : (t.quality_score && t.quality_score.score) || '';
            await logEvent(env, { area: 'מטא', action: `תבנית ${t.name}: ${t.status}${reason ? ' · ' + reason : ''}`, ok: false, review: true, ref: t.name, detail: live === t.name ? 'הוסרה מהשימוש, חזרה לתבנית הקודמת' : 'לא הייתה בשימוש' });
            await slackSend(env, `🚨 *בעיה בתבנית וואטסאפ* · ${t.name}
מצב: ${t.status}${reason ? ' · סיבה: ' + reason : ''}
${live === t.name ? 'המערכת חזרה אוטומטית לתבנית הקודמת, השליחות ממשיכות.' : 'התבנית לא הייתה בשימוש, שום שליחה לא נפגעה.'}
מה עכשיו: ${t.status === 'REJECTED' ? 'לתקן את הנוסח ולהגיש מחדש (אני אעשה כשתגיד)' : 'לבדוק ב-WhatsApp Manager למה מטא השהתה/השביתה'}`, { urgent: true, key: 'template_bad:' + t.name, sev: 'P1' });
          }
        }
      }
    }
  } catch (e) {
    out.tmplcheck = { ok: false, why: String(e && e.message) };
  }
  /* 16/09: 4499 is moving to the Ishur.io portfolio. Meta first has to
     approve the display name "ishur.io" on the number; tell Richard the
     moment it flips, the migration (OTP) needs him on the phone. */
  try {
    if (!clientOnPortfolio(env) && env.WA_TOKEN && clientPhoneId(env) && !(await env.RATE.get('dispname:ok'))) {
      const r = await fetch(`https://graph.facebook.com/v21.0/${clientPhoneId(env)}?fields=new_display_name,new_name_status,name_status,verified_name`, { headers: { Authorization: 'Bearer ' + env.WA_TOKEN } }).catch(() => null);
      const j = r ? await r.json().catch(() => null) : null;
      if (j && (j.new_name_status === 'APPROVED' || j.name_status === 'APPROVED' || j.name_status === 'AVAILABLE_WITHOUT_REVIEW')) {
        await env.RATE.put('dispname:ok', new Date().toISOString());
        await slackSend(env, `✅ מטא אישרה את שם התצוגה של נועה (${j.new_display_name || j.verified_name}). אפשר להעביר את 4499 לפורטפוליו Ishur.io — תגיד לי כשאתה ליד הטלפון לקוד.`, { urgent: true, oneoff: true });   /* oneoff: Meta approved once */
        await logEvent(env, { area: 'מטא', action: 'שם תצוגה אושר ל-4499', ok: true, detail: JSON.stringify(j).slice(0, 200) });
      } else if (j && j.new_name_status === 'DECLINED' && !(await env.RATE.get('dispname:declined'))) {
        await env.RATE.put('dispname:declined', new Date().toISOString(), { expirationTtl: 7 * 86400 });
        await slackSend(env, `🚨 מטא דחתה את שם התצוגה "${j.new_display_name}" ל-4499. צריך שם אחר (למשל "אישורי הגעה ishur.io").`, { urgent: true, oneoff: true });   /* oneoff: Meta rejected once */
      }
    }
  } catch {}
}

qa_digest.source:
async function runQaDigests(env) {
  if (!env.RATE) return;
  const parts = new Intl.DateTimeFormat('en-GB', { timeZone: 'Asia/Jerusalem', weekday: 'short', hour: '2-digit', minute: '2-digit', hour12: false }).formatToParts(new Date());
  const get = t => (parts.find(p => p.type === t) || {}).value;
  const hm = Number(get('hour')) * 60 + Number(get('minute')), wd = get('weekday'), today = ilDate();
  if (hm >= 20 * 60 + 45 && !(await seenOnce(env, 'qadigest:d:' + today))) {
    const d = await qaDigest(env, 1, today);
    if (Number(d.calls) > 0) await slackPost(env, qaDigestText(d), { cls: 'info', key: 'qadigest:d:' + today });
  }
  if (wd === 'Sun' && hm >= 9 * 60 && !(await seenOnce(env, 'qadigest:w:' + today))) {
    await slackPost(env, qaDigestText(await qaDigest(env, 7, today)), { cls: 'info', key: 'qadigest:w:' + today });
  }
}

doctor.source:
async function runDoctor(env, out, sendWin, callWin) {
  if (!env.RATE) return { ok: false, why: 'no-kv' };
  const rep = { fixed: 0, alerted: 0, notes: [] };

  /* 1. build version → journal, once per version */
  try {
    const vid = env.CF_VERSION_METADATA && env.CF_VERSION_METADATA.id;
    if (vid && (await env.RATE.get('build:current')) !== vid) {
      await env.RATE.put('build:current', vid);
      await logEvent(env, { area: 'בנייה', action: 'גרסה חדשה של הוורקר עלתה', ok: true,
        ref: String(vid).slice(0, 8), detail: `version ${vid}` + (env.BUILD_SHA ? ` · git ${env.BUILD_SHA}` : '') + (env.BUILD_NOTE ? ` · ${env.BUILD_NOTE}` : '') });
      rep.notes.push('build:' + String(vid).slice(0, 8));
      /* 03/11 change log: deploy:<version> with the commits since the last deploy + the registry diff */
      await recordDeploy(env, vid, BUILD_INFO, AUTOMATIONS).catch(() => {});
    }
  } catch (e) { rep.notes.push('build-err'); }

  /* 2. parked Grow payments — re-run the matcher, ship what now matches */
  try {
    const page = await env.RATE.list({ prefix: 'ipnmiss:', limit: 20 });
    let stuck = 0;
    for (const k of page.keys) {
      const raw = await env.RATE.get(k.name);
      if (!raw) continue;
      let flat; try { flat = JSON.parse(raw); } catch { continue; }
      if (looksIshur(flat, [])) {
        const r = await processGrowPayment(env, flat).catch(() => null);
        const st = r ? r.status : 0;
        await logEvent(env, { area: 'רופא', action: 'תשלום שחנה זוהה מחדש והורץ אוטומטית', ok: st === 200, review: st !== 200,
          phone: flat.payerPhone || flat.phone || '', ref: flat.asmachta || '', detail: `${k.name} → ${st}` });
        if (st === 200) { await env.RATE.delete(k.name); rep.fixed++; }
        else stuck++;
      } else {
        stuck++;
      }
    }
    /* Richard, 05/10: the parked Grow payments are other businesses on the
       same Grow account. Say it ONCE per payment, never a daily reminder:
       only keys that were never announced trigger the Slack line. */
    if (stuck) {
      let told = []; try { told = JSON.parse(await env.RATE.get('doctor:ipnmiss-told') || '[]'); } catch {}
      const fresh = page.keys.map(k => k.name).filter(n => !told.includes(n));
      if (fresh.length) {
        /* info, not a red row: the nightly report must not re-list it (Richard 06/10) */
        const ipnMsg = `${fresh.length} תשלומי Grow חדשים חונים ולא זוהו כ-ishur (סה"כ ${stuck}). אם אחד מהם לקוח שלנו: /api/ipn-replay עם המזהה מיומן המערכת. לא אזכיר שוב.`;
        await logEvent(env, { area: 'רופא · תשלומים שחנו', action: ipnMsg, ok: true, review: false }).catch(() => {});
        if (env.SLACK_ALERT_HOOK) await slackSend(env, 'ℹ️ *רופא · תשלומים שחנו* · ' + ipnMsg, { urgent: false, cls: 'info', key: 'doctor:ipnmiss' }).catch(() => {});
        rep.alerted++;
        await env.RATE.put('doctor:ipnmiss-told', JSON.stringify(told.concat(fresh).slice(-200))).catch(() => {});
      }
    }
  } catch (e) { rep.notes.push('ipnmiss-err'); }

  /* 3. stale pacer day — re-arm so the send slice runs today */
  try {
    const today = ilDate();
    const pending = await env.RATE.get('pacer:pending');
    if (sendWin && sendWin.open && pending && pending !== today && !isNoContactDay(today)) {
      await env.RATE.put('pacer:pending', today, { expirationTtl: 2 * 86400 });
      await logEvent(env, { area: 'רופא', action: 'יום שליחה לא חומש — חומש מחדש', ok: true, detail: `pacer:pending היה ${pending}, עכשיו ${today}` });
      rep.fixed++;
    }
  } catch (e) { rep.notes.push('pacer-err'); }

  /* 4. journal flush failing twice in a row */
  try {
    const j = out && out.journal;
    if (j && !j.ok && j.why !== 'not-configured') {
      const n = (parseInt(await env.RATE.get('doctor:flushfail') || '0', 10) || 0) + 1;
      await env.RATE.put('doctor:flushfail', String(n), { expirationTtl: 3600 });
      if (n >= 2 && await onceADay(env, 'flush')) {
        await alert(env, 'רופא · יומן המערכת', `שטיפת היומן לגיליון נכשלה ${n} פעמים ברצף (${j.why || ''}${j.pending ? ` · ${j.pending} שורות ממתינות` : ''}). השורות נשמרות ב-KV ומנסות שוב כל 10 דקות`, '', { key: 'doctor:journal', level: n, bands: [3, 6, 12] });
        rep.alerted++;
      }
    } else if (j && j.ok) {
      await env.RATE.delete('doctor:flushfail').catch(() => {});
    }
  } catch (e) { rep.notes.push('flush-err'); }

  /* 5. the dial queue went silent because the snapshot could not be read */
  try {
    const c = out && out.calls;
    if (callWin && callWin.open && c && c.why === 'reader-failed' && await onceADay(env, 'reader')) {
      await alert(env, 'רופא · תור השיחות', 'חלון החיוג פתוח אבל תמונת הגיליון לא נקראת (Make Status). שיר לא מחייגת עד שזה חוזר', '', { key: 'doctor:callqueue', sev: 'P1' });
      rep.alerted++;
    }
  } catch (e) { rep.notes.push('reader-err'); }

  /* 6. Meta template check failed */
  try {
    const t = out && out.tmplcheck;
    if (t && !t.ok && await onceADay(env, 'tmpl')) {
      await alert(env, 'רופא · תבניות מטא', `בדיקת אישור התבניות השעתית נכשלה: ${t.why || ''}. ההפעלה האוטומטית של תבנית התמונה/החשבונית מתעכבת`, '', { key: 'doctor:templates' });
      rep.alerted++;
    }
  } catch (e) { rep.notes.push('tmpl-err'); }

  return { ok: true, ...rep };
}

sheet_outbox.source:
const outbox = await step('sheet_outbox', () => drainSheetQueue(env, sheetBatchPost, { cap: 25 })).catch(e => ({ ok: false, error: String((e && e.message) || e) }));
if (isNoContactDay(today)) { const quiet = { ok: true, skipped: 'no-contact-day' }; await templateCheck(env, quiet); return quiet; }

/* Phase 6: flush last night's queued Slack alerts once the 09:00 window
   opens. No new cron needed — the pacer already ticks every 10 minutes;
   this just needs to notice the hour crossed 9 and hasn't flushed yet
   today. Runs even while sending is paused — a paused system is exactly
   when Richard still wants to see what queued overnight. */
const ilHour = Number(new Intl.DateTimeFormat('en-US', { timeZone: 'Asia/Jerusalem', hour: '2-digit', hour12: false }).format());
if (ilHour >= 9 && await env.RATE.get('slackqflush:' + today) !== '1') {
  await env.RATE.put('slackqflush:' + today, '1', { expirationTtl: 2 * 86400 }).catch(() => {});
  /* 04/11 slack-gate: the 09:00 "בוקר · סיכום" (slack-gate.js slackDigest) replaces the bare night-queue
     flush — open conditions, what resolved overnight, the info lines, the night queue and today's plan,
     ONE message. Kill switch auto:off:slack_digest (registry node slack_digest) → the old flush runs
     instead so the night queue never piles up. */
  if (await isOff(env, 'slack_digest')) await flushSlackQueue(env).catch(() => {});
  else await step('slack_digest', () => slackDigest(env, { post: t => slackSend(env, t, { oneoff: true, urgent: true, digest: true }), plan: () => digestPlan(env) })).catch(() => {});   /* oneoff: the one daily digest */
}
/* ads health, once an hour inside Slack hours (the alert itself is
   urgent, so quiet hours are respected by not asking at night) */
if (ilHour >= 9 && ilHour < 21) {
  const hk = 'adshealth:' + today + ':' + ilHour;
  if (await env.RATE.get(hk) !== '1') {
    await env.RATE.put(hk, '1', { expirationTtl: 2 * 86400 }).catch(() => {});
    await adsHealthAlert(env).catch(() => {});
  }
}

if (await sendingPaused(env)) return { ok: true, paused: true };

const out = { date: today };
if (outbox && !outbox.idle) out.sheet_outbox = { drained: outbox.drained || 0, left: outbox.left || 0, ok: !!outbox.ok };

/* messages first: they are cheaper and they warm the 24h window a call
   lands in more gracefully than a cold ring does */
const sendWin = sendWindowState();
/* 22/10 Richard: guests whose invitation failed (130472/131049/131026, not
   yet 3 strikes) are retried automatically once per send day; before this
   it only happened when someone ran /api/wave-retry by hand. */
/* 03/11: auto:off:autoretry skips it WITHOUT burning autoretry:<day>, so switching it back on the same day still runs it */

