late_invites.source:
async function drainLateInvites(env) {
  if (!env.RATE || !sendWindowState().open) return { sent: 0, closed: true };
  const q = await kvPrefix(env, 'lateinv:');
  const keys = Object.keys(q);
  if (!keys.length) return { sent: 0 };
  const raw = await snapshotCached(env, 'send');
  /* 04/11: without a snapshot every queued invite looked "event not found" and was deleted */
  if (!raw) return { sent: 0, queued: keys.length, why: snapMiss(env) };
  const evRows = (raw && raw.events && raw.events.values) || [];
  let sent = 0, tried = 0;
  for (const k of keys) {
    if (tried >= 10) break;
    const [tok, phone] = k.split(':');
    let rec = {}; try { rec = JSON.parse(q[k]) || {}; } catch {}
    const ev = evRows.find(r => String((r || [])[1] || '').trim() === tok);
    if (!ev) { await env.RATE.delete('lateinv:' + k).catch(() => {}); continue; }
    tried++;
    const r = await lateInvite(env, ev, tok, rec.name, phone);
    if (r.sent) sent++;
    if (/^queued:budget/.test(r.why)) break;   /* the budget is out — the rest waits */
  }
  return { sent, tried, queued: keys.length };
}

calendar_build.source:
async function buildCalendarMonth(env, month) {
  const y = Number(month.slice(0, 4)), mo = Number(month.slice(5, 7));
  const mFirst = month + '-01', mLast = new Date(Date.UTC(y, mo, 0)).toISOString().slice(0, 10);
  const today = ilDate();
  const raw = await readSnapshot(env, 'background');
  const evRows = (raw && raw.events && raw.events.values) || [];
  const gRows = (raw && raw.guests && raw.guests.values) || [];
  const evByTok = {}; const nameByPhone = {};
  for (const ev of evRows) {
    const t = String(ev[1] || '').trim(); if (!t) continue;
    const name = String(ev[2] || '').trim(); const occ = String(ev[5] || '').trim();
    evByTok[t] = { token: t, tok8: t.slice(0, 8), client: name, phone: normPhone(ev[3] || ''), occasion: occ, event: (occ ? 'ה' + occ : 'האירוע') + ' של ' + (String(ev[34] || '').trim() || name),
      date: String(ev[6] || '').trim().slice(0, 10), paid: String(ev[7] || '').trim() === 'כן', cancelled: String(ev[27] || '').trim() === 'כן',
      w: [String(ev[39] || '').trim().slice(0, 10), String(ev[40] || '').trim().slice(0, 10), String(ev[41] || '').trim().slice(0, 10)], fileUp: String(ev[43] || '').trim() === 'כן' };
    if (evByTok[t].phone) nameByPhone[evByTok[t].phone] = { name, tok: t, kind: 'לקוח' };
  }
  const leadRows = await leadsTabCached(env).catch(() => []);   /* 04/11 Make burn: was a Make read every tick */
  for (const l of leadRows) { const ph = normPhone(l[2] || ''); if (ph && !nameByPhone[ph]) nameByPhone[ph] = { name: String(l[1] || '').trim(), tok: '', kind: 'ליד' }; }
  const guestsByTok = {};
  for (const g of gRows) {
    const t = String(g[28] || '').trim(); const ph = normPhone(g[4] || ''); if (!t || !ph) continue;
    (guestsByTok[t] = guestsByTok[t] || []).push({ phone: ph, name: String(g[3] || '').trim(), rsvp: String(g[15] || '').trim(), table: String(g[30] || '').trim(), id: String(g[2] || '').trim() });
    if (!nameByPhone[ph]) nameByPhone[ph] = { name: String(g[3] || '').trim(), tok: t, kind: 'אורח' };
  }
  const days = {};
  const day = d => (days[d] = days[d] || []);
  /* past: every log entry of the month */
  const names = await kvKeys(env, 'log:', 60000);
  const fromTs = Date.parse(mFirst + 'T00:00:00+03:00'), toTs = Date.parse(mLast + 'T23:59:59+03:00');
  const inMonth = names.filter(n => { const ts = Number(n.split(':').pop()); return ts >= fromTs && ts <= toTs; });
  const vals = await Promise.all(inMonth.map(n => env.RATE.get(n).catch(() => null)));
  inMonth.forEach((n, i) => {
    let v = null; try { v = JSON.parse(vals[i]); } catch {}
    if (!v || v.dir !== 'out') return;
    const phone = n.split(':')[1]; const ts = Number(n.split(':').pop());
    const d = new Date(ts + 3 * 3600e3).toISOString().slice(0, 10);
    const who = nameByPhone[phone] || {};
    const tok = v.tok ? Object.keys(evByTok).find(t => t.startsWith(v.tok)) : who.tok;
    day(d).push({ at: v.at || new Date(ts).toISOString(), phone, name: who.name || '', kind: who.kind || (v.ch === 'guests' ? 'אורח' : 'לקוח/ליד'), ch: v.ch || 'client',
      token: tok || '', event: tok && evByTok[tok] ? evByTok[tok].event : '', what: v.tmpl || (v.type === 'text' ? 'טקסט' : v.type || ''),
      status: v.ok === false ? 'failed' : (v.status || 'sent'), error: v.error || '', text: String(v.text || '').slice(0, 120), done: true });
  });
  /* future: what the engine will do, per event, per date in the month */
  const KINDS = { 1: 'הזמנה (גל 1)', 2: 'תזכורת (גל 2)', 3: 'שליחה נוספת (גל 3)', daybefore: 'יום לפני', shulchan: 'שולחן ביום האירוע', toda: 'תודה יום אחרי', eoe: 'סיכום ללקוח' };
  const markerOf = (kind, tok, ph) => kind === 'daybefore' ? `s5d:${tok}:${ph}` : kind === 'shulchan' ? `s5t:${tok}:${ph}` : kind === 'toda' ? `s3t:${tok}:${ph}` : `wsent:${tok}:${kind}:${ph}`;
  const skipChecks = [];
  for (const t of Object.keys(evByTok)) {
    const ev = evByTok[t]; if (!ev.paid || ev.cancelled) continue;
    const gl = guestsByTok[t] || [];
    const plan = (d, kind, list) => { if (!d || d < mFirst || d > mLast || d < today) return; for (const g of list) { const e = { at: d + 'T09:00:00', phone: g.phone, name: g.name, kind: 'אורח', ch: 'guests', token: t, event: ev.event, what: KINDS[kind], k: String(kind), status: 'planned', done: false, skipped: false }; day(d).push(e); skipChecks.push([e, markerOf(kind, t, g.phone)]); } };
    const notDeclined = gl.filter(g => g.rsvp !== 'לא מגיע');
    if (ev.w[0]) plan(ev.w[0], 1, notDeclined);
    if (ev.w[1]) plan(ev.w[1], 2, gl.filter(g => g.rsvp === '' || g.rsvp === 'מתלבט'));
    if (ev.w[2]) plan(ev.w[2], 3, notDeclined);
    const conf = gl.filter(g => g.rsvp === 'מגיע');
    if (ev.date) {
      const dm1 = new Date(Date.parse(ev.date) - 864e5).toISOString().slice(0, 10);
      const dp1 = new Date(Date.parse(ev.date) + 864e5).toISOString().slice(0, 10);
      plan(dm1, 'daybefore', conf);
      plan(ev.date, 'shulchan', conf.filter(g => g.table));
      plan(dp1, 'toda', conf);
      if (dp1 >= mFirst && dp1 <= mLast && dp1 >= today && ev.phone) day(dp1).push({ at: dp1 + 'T09:00:00', phone: ev.phone, name: ev.client, kind: 'לקוח', ch: 'client', token: t, event: ev.event, what: KINDS.eoe, k: 'eoe', status: 'planned', done: false });
    }
  }
  /* which planned rows are already skipped (marker pre-set by the admin) */
  const marks = await Promise.all(skipChecks.map(([, k]) => env.RATE.get(k).catch(() => null)));
  skipChecks.forEach(([e], i) => { if (marks[i]) { e.skipped = true; e.status = marks[i] === 'skip' ? 'skipped' : 'done-earlier'; } });
  /* Richard 12/10: "if it's planned I want to know for what time". The
     engine does not fire everything at 09:00: the morning run sends its
     first slice when the window is open (09:35 IL in summer, 50 messages),
     and the 10-minute pacer carries 25 per tick from 09:00 onwards. The
     time below walks that schedule in the engine's own order (waves per
     event first, then day-before / table / thanks / client summary), so
     it is an estimate, marked as one on the page. */
  const STAGE = { 1: 0, 2: 0, 3: 0, daybefore: 1, shulchan: 2, toda: 3, eoe: 4 };
  const ilHourAt = (d, hUtc, mUtc) => Number(new Intl.DateTimeFormat('en-GB', { timeZone: 'Asia/Jerusalem', hour: '2-digit', hour12: false }).format(new Date(`${d}T${String(hUtc).padStart(2, '0')}:${String(mUtc).padStart(2, '0')}:00Z`)));
  const nowMin = (() => { const p = new Intl.DateTimeFormat('en-GB', { timeZone: 'Asia/Jerusalem', hour: '2-digit', minute: '2-digit', hour12: false }).formatToParts(new Date()); const g = t => Number((p.find(x => x.type === t) || {}).value || 0); return g('hour') * 60 + g('minute'); })();
  for (const d of Object.keys(days)) {
    const rows = days[d];
    const planned = rows.map((e, i) => ({ e, i })).filter(x => x.e.status === 'planned');
    if (planned.length) {
      const dow = new Date(d + 'T12:00:00Z').getUTCDay();
      const close = dow === 5 ? 13 * 60 : 20 * 60 + 30;
      /* summer: the 06:35 UTC morning run lands inside the window and sends 50 at 09:35; winter: it lands at 08:35, sends nothing, and the pacer starts at 09:00 */
      const summer = ilHourAt(d, 6, 35) === 9;
      let slot = summer ? 9 * 60 + 35 : 9 * 60, cap = summer ? PACE_SENDS * 2 : PACE_SENDS;
      if (d === today && nowMin > slot) { slot = Math.ceil(nowMin / 10) * 10; cap = PACE_SENDS; }
      planned.sort((x, y) => (STAGE[x.e.k] ?? 9) - (STAGE[y.e.k] ?? 9) || x.i - y.i);
      let used = 0;
      for (const { e } of planned) {
        if (used >= cap) { slot = Math.floor(slot / 10) * 10 + 10; cap = PACE_SENDS; used = 0; }   // next pacer tick (:00, :10, :20…)
        if (slot > close) { e.late = true; e.at = d + 'T' + String(Math.floor(close / 60)).padStart(2, '0') + ':' + String(close % 60).padStart(2, '0') + ':00'; continue; }
        e.at = d + 'T' + String(Math.floor(slot / 60)).padStart(2, '0') + ':' + String(slot % 60).padStart(2, '0') + ':00';
        e.est = true; used++;
      }
    }
    rows.sort((a, b) => a.at < b.at ? -1 : 1);
  }
  const calOut = { ok: true, month, today, days, events: Object.values(evByTok).map(e => ({ token: e.token, tok8: e.tok8, client: e.client, event: e.event, date: e.date })) };
  if (env.RATE) await env.RATE.put('calcache:' + month, JSON.stringify({ at: Date.now(), data: calOut }), { expirationTtl: 1200 }).catch(() => {});
  return calOut;
}

noa_chase.source:
export async function noaChaseTick(env, deps = {}) {
  if (!on(env)) return { ok: true, why: 'noa-chase-off' };
  const out = {};
  try { out.scan = await scanMondayNotAnswered(env, { deps }); } catch (e) { out.scan = { ok: false, why: String(e && e.message) }; }
  try { out.drain = await drainNoaChase(env, { max: 2, deps: { ...deps, memory: await memoryBlock(env, 'נועה') } }); } catch (e) { out.drain = { ok: false, why: String(e && e.message) }; }
  if (out.drain && out.drain.dialed) {
    await slackPost(env, `📞 *נועה יצאה ל-${out.drain.dialed} שיחות רדיפה* ללידים מהלוח שלא ענו.`, { quiet: true, oneoff: true }).catch(() => {});   /* oneoff: one dial batch (quiet) */
  }
  stream(env, { kind: 'event', area: 'נועה', action: 'סבב רדיפה', ok: true, detail: JSON.stringify({ scan: out.scan && { queued: (out.scan.queued || []).length, skipped: (out.scan.skipped || []).length, why: out.scan.why }, drain: out.drain }).slice(0, 600) }).catch(() => {});
  return out;
}

audit_meta.source:
export async function refreshMeta(env, raw) {
  if (!env.RATE || !raw) return { events: 0 };
  const evs = ((raw.events && raw.events.values) || []).filter(r => /^[0-9a-f-]{36}$/.test(String((r || [])[1] || '').trim()));
  const guests = ((raw.guests && raw.guests.values) || []);
  const byTok = {};
  for (const g of guests) { const t = String((g || [])[28] || '').trim(); if (!t) continue; const ph = String(g[4] || '').replace(/\D/g, '').replace(/^0/, '972'); if (!ph) continue; (byTok[t] = byTok[t] || {})[ph] = { id: String(g[2] || '').trim(), name: String(g[3] || '').trim(), seats: String(g[13] || g[5] || '').trim(), rsvp: String(g[15] || '').trim(), table: String(g[30] || '').trim(), call: String(g[21] || '').trim() }; }
  let n = 0;
  for (const r of evs) {
    const c = i => String(r[i] ?? '').trim();
    const tok = c(1);
    const meta = { event: c(34) || c(2), occasion: c(5), date: c(6).slice(0, 10), time: c(36), venue: c(4), city: c(37), client: c(2), client_phone: c(3), plan: c(31) || '', tier: c(32) || '', paid: c(8) || '', cancelled: c(27) === 'כן', invite_date: c(39), reminder_date: c(40) };
    await env.RATE.put('evmeta:' + tok, JSON.stringify(meta), { expirationTtl: 2 * 86400 }).catch(() => {});
    await env.RATE.put('gmap:' + tok, JSON.stringify(byTok[tok] || {}), { expirationTtl: 2 * 86400 }).catch(() => {});
    n++;
  }
  return { events: n };
}

ab_evaluate.source:
export async function evaluate(env, deps = {}) {
  const kv = kvOf(env, deps);
  if (!kv) return { ok: false, why: 'no-kv' };
  if (String(env.AB_ENABLED || '') !== 'on' && !deps.force) return { ok: true, skipped: 'ab-off' };
  const now = deps.now ? deps.now() : Date.now();
  const day = new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Jerusalem' }).format(new Date(now)).replace(/-/g, '');
  if (!deps.force && await kv.get('ab:eval:' + day)) return { ok: true, skipped: 'already-ran' };
  await kv.put('ab:eval:' + day, '1', { expirationTtl: 3 * 86400 });

  clearMemo(env);
  const tests = await loadTests(env, deps);
  let history = [];
  try { history = JSON.parse((await kv.get('ab:history')) || '[]') || []; } catch { history = []; }
  const notify = deps.notify || (async () => {});
  const report = [];

  let qualityOk = false;
  try {
    const q = deps.numberQuality ? await deps.numberQuality() : [];
    qualityOk = q.length > 0 && q.every(n => String(n.quality || '').toUpperCase() === 'GREEN');
  } catch { qualityOk = false; }

  for (const [msgType, t] of Object.entries(tests)) {
    t.quality_ok = qualityOk;
    if (t.status === 'needs_draft') { report.push({ msgType, id: t.id, action: 'needs_draft', challenger: t.challenger }); continue; }
    if (t.status === 'pending') {
      const ok = deps.isApproved ? await deps.isApproved(t.challenger) : false;
      if (ok) {
        t.status = 'running'; t.started_at = new Date(now).toISOString();
        if (deps.categoryOf) t.category = (await deps.categoryOf(t.challenger)) || t.category;
        report.push({ msgType, id: t.id, action: 'started' });
        await notify(`🧪 ניסוי נוסחים התחיל · ${msgType} · ${t.control} מול ${t.challenger}`);
      } else report.push({ msgType, id: t.id, action: 'waiting-approval' });
      continue;
    }
    if (t.status !== 'running') continue;

    /* the challenger must still be APPROVED (Meta can pause/disable a template) */
    if (deps.isApproved && !(await deps.isApproved(t.challenger))) {
      t.status = 'stopped'; t.ended_at = new Date(now).toISOString(); t.reason = 'challenger-not-approved';
      report.push({ msgType, id: t.id, action: 'stopped', reason: t.reason });
      await notify(`⏸ ניסוי ${t.id} נעצר: ${t.challenger} כבר לא מאושרת במטא`);
      continue;
    }
    const keys = await listAll(kv, `ab:o:${t.id}:`);
    const assignments = keys.map(k => { const p = k.name.split(':'); return { arm: p[3], wamid: p.slice(4).join(':'), ts: (k.metadata && k.metadata.ts) || 0 }; });
    const since = Math.min(...assignments.map(a => a.ts || now), Date.parse(t.started_at || new Date(now).toISOString()));
    /* queryRows may answer { rows, missing } (template-stats loadRows): never
       decide on a partial log — a missing day could hold one arm's replies */
    const got = deps.queryRows ? await deps.queryRows(env, since) : [];
    const rows = Array.isArray(got) ? got : ((got && got.rows) || []);
    const missing = Array.isArray(got) ? [] : ((got && got.missing) || []);
    if (missing.length) { report.push({ msgType, id: t.id, action: 'incomplete-data', missing }); continue; }
    const stats = armStats(assignments, rows, now);
    const d = decide(stats);
    t.looks = [...(t.looks || []), { at: new Date(now).toISOString(), n: d.n, z: Math.round(d.z * 100) / 100, bound: d.bound && Math.round(d.bound * 100) / 100, c: stats.control.rate, x: stats.challenger.rate }].slice(-60);
    report.push({ msgType, id: t.id, action: d.action, decision: d, stats });
    if (d.action === 'continue') continue;

    /* finished: record, rotate, queue the next challenger */
    t.status = d.action === 'stop_optout' ? 'stopped' : 'done';
    t.ended_at = new Date(now).toISOString();
    t.winner = d.winner === 'challenger' ? t.challenger : t.control;
    t.reason = d.reason;
    t.final = stats;
    const loserArm = d.winner === 'challenger' ? 'control' : 'challenger';
    history = [{ ...t }, ...history].slice(0, 50);
    if (d.winner === 'challenger') {
      await kv.put('ab:control:' + msgType, t.challenger);
      if (String(env.AB_AUTOROTATE || '') === 'on' && deps.promote) await deps.promote(msgType, t.challenger);
    }
    const control = t.winner;
    const next = {
      id: `${msgType}-${day}-${hashUnit(control + now).toString(36).slice(2, 7)}`,
      msg_type: msgType, control, challenger: nextChallengerName(control, history, {}),
      category: t.category || '', split: t.split == null ? 0.5 : t.split, status: 'needs_draft',
      created_at: new Date(now).toISOString(), brief: weaknesses(stats, loserArm),
    };
    tests[msgType] = next;   // one challenger per message type, always
    await notify(`🏁 ניסוי ${t.id} (${msgType}) הסתיים · מנצחת: ${t.winner} · ${d.reason}` +
      (d.winner === 'challenger' && String(env.AB_AUTOROTATE || '') !== 'on' ? ' · ההחלפה לייצור ממתינה לאישור ריצארד' : '') +
      ` · המתחרה הבאה: ${next.challenger} (טיוטה)`);
  }
  await saveTests(env, deps, tests);
  await kv.put('ab:history', JSON.stringify(history));
  return { ok: true, day, quality_ok: qualityOk, report };
}

call_cost_sync.source:
async function syncCallCosts(env, limit = 100) {
  if (!env.RETELL_KEY || !env.RATE) return { ok: false, why: 'not-configured' };
  const calls = await retellListCalls(env, { limit, sort_order: 'descending' });
  if (!calls) return { ok: false, why: 'retell-unreachable' };

  let added = 0, skipped = 0, cents = 0;
  for (const c of calls) {
    const id = String(c.call_id || '');
    if (!id) continue;
    /* one call is counted once, ever */
    if (await env.RATE.get('costdone:' + id)) { skipped++; continue; }
    const cc = c.call_cost || {};
    const amount = typeof cc.combined_cost === 'number' ? cc.combined_cost : 0;
    if (!amount || !c.end_timestamp) continue; // still running, or free
    const day = new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Jerusalem' })
      .format(new Date(c.end_timestamp));
    const key = 'shircost:' + day;
    const cur = Number(await env.RATE.get(key)) || 0;
    await env.RATE.put(key, String(cur + amount), { expirationTtl: 400 * 86400 });
    /* and onto the event, so per-event profit includes the calls */
    const gid = String((c.metadata || {}).guest_id || '');
    if (gid) await addEvCost(env, gid, amount);
    await env.RATE.put('costdone:' + id, '1', { expirationTtl: 400 * 86400 });
    added++; cents += amount;
  }
  return { ok: true, added, skipped, cents: Math.round(cents * 100) / 100,
           ils: Math.round(cents / 100 * USD_ILS * 100) / 100 };
}

manual_blasts.source:
async function handleGiftBlast(request, env, origin) {
  let b = {}; try { b = await request.json(); } catch { return deny(400, 'bad-json', origin); }
  if (!isAdmin(env, b.admin_key)) return deny(403, 'bad-admin-key', origin);
  const token = String(b.token || '').trim();
  if (!/^[0-9a-f-]{36}$/.test(token)) return deny(400, 'bad-token', origin);
  const dry = b.dry !== false;
  const max = Math.max(1, Math.min(500, Number(b.max) || 50));
  const raw = await readSnapshot(env, 'send');
  if (!raw) return deny(502, snapMiss(env), origin);
  const ev = eventRowOf(raw, token);
  if (!ev) return deny(404, 'unknown-token', origin);
  const today = ilDate();
  const hour = Number(new Intl.DateTimeFormat('en-US', { timeZone: 'Asia/Jerusalem', hour: '2-digit', hour12: false }).format());
  const paused = await sendingPaused(env).catch(() => false);
  const win = sendWindowState();
  const windowOpen = win.open && !isNoContactDay(today) && !paused;
  const gl = await giftLinksOf(env, token);
  const evName = eventDisplayName(ev, { article: false, fallback: 'אירוע' });   /* "ב{{2}}" / "ל{{2}}" */
  const guests = []; const seen = new Set();
  for (const g of (raw.guests && raw.guests.values) || []) {
    if (String(g[28] || '').trim() !== token) continue;
    const phone = normPhone(g[4] || ''); if (!phone || seen.has(phone)) continue; seen.add(phone);
    guests.push({ phone, name: String(g[3] || '').trim(), rsvp: String(g[15] || '').trim() });
  }
  const sentMarks = new Set(), blocked = new Set();
  for (let i = 0; i < guests.length; i += 25) {
    await Promise.all(guests.slice(i, i + 25).map(async g => {
      if (g.rsvp !== 'מגיע' && g.rsvp !== 'לא מגיע') return;
      const [gm, th] = await Promise.all([env.RATE.get(giftKey(token, g.phone)).catch(() => null), g.rsvp === 'מגיע' ? env.RATE.get(`s3t:${token}:${g.phone}`).catch(() => null) : null]);
      if (gm || th) sentMarks.add(g.phone);
      if (await phoneBlocked(env, g.phone) || await wrongNum(env, token, g.phone)) blocked.add(g.phone);
    }));
  }
  const [thanksTmpl, declinedTmpl, cap] = await Promise.all([
    giftTemplateFor(env, 'thanks'),
    giftTemplateFor(env, 'declined'),
    guestCapacity(env).catch(() => ({ remaining: 0, limit: 0, used: 0, scope: '' })),
  ]);
  const thanksOk = !!thanksTmpl, declinedOk = !!declinedTmpl;
  const plan = planGiftBlast({ today, eventDate: String(ev[6] || '').trim().slice(0, 10), hour, windowOpen, gl, guests, sentMarks, blocked,
    room: cap.remaining, max, templates: { thanks: thanksTmpl, declined: declinedTmpl } });
  const head = { token: token.slice(0, 8), event: eventDisplayName(ev), event_date: String(ev[6] || '').slice(0, 10), today, hour, dry, max,
    window: { ...win, paused, no_contact_day: isNoContactDay(today) }, gift_links: { on: !!(gl && gl.on), bit: !!(gl && gl.bit), paybox: !!(gl && gl.paybox), page: giftActive(gl) ? 'https://go.ishur.io/gift/' + giftSlug(token) : '' },
    templates: { thanks: thanksTmpl || 'not approved', declined: declinedTmpl || 'not approved' },
    cap: { scope: cap.scope, limit: cap.limit, used: cap.used, remaining: cap.remaining } };
  if (plan.refuse) return okJson({ ok: false, refused: plan.why, ...head }, origin);
  const mask = p => p.replace(/^972/, '0').replace(/(\d{3})\d{4}(\d{3})$/, '$1-****-$2');
  if (dry) return okJson({ ok: true, ...head, counts: plan.counts, guests: plan.list.map(x => ({ ...x, phone: mask(x.phone) })) }, origin);
  let sent = 0, failed = 0;
  const results = [];
  for (const x of plan.list) {
    if (x.action !== 'send') { results.push({ ...x, phone: mask(x.phone) }); continue; }
    const gname = x.name || 'אורחים יקרים';
    const wa = await sendTemplate(env, x.phone, x.template, [gname, evName], '', 'he', 'guests', { token, wave: 'gift', name: gname, who: 'שיר (מתנה)', components: [giftButtonComponent(token)] });
    if (wa.ok) {
      sent++;
      const gk = giftKey(token, x.phone);
      await env.RATE.put(gk, JSON.stringify({ at: new Date().toISOString(), via: 'blast', tmpl: x.template }), { expirationTtl: 120 * 86400 }).catch(() => {});
      await noteGuestSend(env, wa, token, 'gift', x.phone, gk);
      /* a confirmed guest's thank-you is THIS message — the day-after stage must not send another */
      if (x.kind === 'thanks') await env.RATE.put(`s3t:${token}:${x.phone}`, today, { expirationTtl: 60 * 86400 }).catch(() => {});
      await addEvCost(env, token, msgCost(x.template)).catch(() => {});
      results.push({ ...x, phone: mask(x.phone), result: 'sent', wamid: wa.id || '' });
    } else {
      failed++;
      results.push({ ...x, phone: mask(x.phone), result: wa.held ? 'held' : 'failed', error: String(wa.error || '').slice(0, 160) });
      if (wa.held) break;   /* the cap closed under us — stop, the rest stays for later */
    }
  }
  await logEvent(env, { area: 'שליחה', action: 'מתנה לאורחים אחרי האירוע (gift-blast)', ok: !failed, review: !!failed, token, detail: `נשלחו ${sent} · נכשלו ${failed} · ממתינים ${plan.counts.hold} · דולגו ${plan.counts.skip}` }).catch(() => {});
  if (sent || failed) await slackPost(env, `🎁 *מתנה לאורחים* · ${head.event}: נשלחו ${sent}${failed ? ` · נכשלו ${failed}` : ''}${plan.counts.hold ? ` · ממתינים ${plan.counts.hold}` : ''}`, { oneoff: true }).catch(() => {});   /* oneoff: a send completed */
  return okJson({ ok: true, ...head, counts: { ...plan.counts, sent, failed }, guests: results }, origin);
}

brain_health.source:
export async function runBrain(env, d, opts = {}) {
  return withRun(env, 'brain_health', async (run) => {
    const L = makeLogger(run.id, 'brain_health');
    const c = makeCtx(env, d, opts, L.log);
    const lastState = (await kjson(env, P.last)) || { checks: {} };
    const only = opts.only ? [].concat(opts.only) : null;
    const checks = CHECKS.filter(k => (only ? only.includes(k.id) : opts.force || due(k, (lastState.checks[k.id] || {}).at, c.now)));
    L.log(`בדיקות שרצות עכשיו: ${checks.map(k => k.id).join(', ') || 'אין'}`);
    const results = []; const failedChecks = []; const checkState = { ...lastState.checks };
    for (const k of checks) {
      let rs = [];
      try { rs = (await k.run(c)) || []; checkState[k.id] = { at: c.now, status: rs.some(r => r.status === 'fail') ? 'fail' : rs.some(r => r.status === 'warn') ? 'warn' : 'ok', n: rs.length }; }
      catch (e) { failedChecks.push(k.id); rs = [{ id: k.id + ':error', status: 'warn', severity: 'P3', title_he: `הבדיקה ${k.id} נפלה`, detail: String(e && e.message || e).slice(0, 200) }]; checkState[k.id] = { at: c.now, status: 'error' }; }
      for (const r of rs) results.push({ ...r, check_id: k.id });
      L.log(`${k.id}: ${rs.length ? rs.map(r => r.status + ' · ' + r.title_he).join(' | ') : 'ok'}`);
      run.count('checks');
    }
    /* findings */
    const idx = await loadIndex(env);
    const prev = {};
    await Promise.all(Object.entries(idx.f).filter(([, m]) => m.state !== 'resolved').map(async ([id]) => { const f = await kjson(env, P.finding + id); if (f) prev[id] = f; }));
    /* the per-check :error finding resolves when the check runs clean again */
    const ran = checks.map(k => k.id);
    const { next, events } = mergeFindings(prev, results, { now: c.now, ranChecks: ran, failedChecks });
    const autofix = String(env.BRAIN_AUTOFIX || 'on') !== 'off';
    for (const ev of events) {
      const f = ev.f; let dirty = ev.type !== 'seen';
      if (ev.type === 'resolved') { L.log(`נפתר: ${f.title_he}`); run.count('resolved'); await obsoletePending(env, f.id); await c.resolveSlack(f.slack_key || 'finding:' + f.id); }
      else {
        if (ev.type === 'new' || ev.type === 'reopened') { L.log(`ממצא ${ev.type === 'new' ? 'חדש' : 'חוזר'} (${f.status}/${f.severity}): ${f.title_he}`); run.count('new'); }
        if (shouldAlert(f, c.now)) { await c.slack(`${f.severity === 'P1' ? '🚨' : '⚠️'} *מוח · ${f.title_he}*${f.detail ? '\n' + f.detail : ''}${f.playbook ? `\nפלייבוק: ${(PB[f.playbook] || {}).name_he || f.playbook}${PB[f.playbook] && PB[f.playbook].auto ? ' (אוטומטי)' : ' — מחכה לאישור בלוח הבקרה'}` : ''}`, f.severity === 'P1', { key: f.slack_key || 'finding:' + f.id, ...(String(f.slack_key || '').startsWith('stuck:') ? { important: true } : {}), sev: f.severity === 'P1' ? 'P0' : f.severity === 'P2' ? 'P1' : 'P2', action: f.playbook && PB[f.playbook] && !PB[f.playbook].auto ? 'לאשר את הפלייבוק במסך המוח — ishur.io/ops.html#/brain' : 'לבדוק במסך המוח — ishur.io/ops.html#/brain?focus=' + f.id }); f.alerted_at = new Date(c.now).toISOString(); dirty = true; run.count('alerted'); L.log('התראה לסלאק'); }
        const pb = f.playbook && PB[f.playbook];
        if (pb && pb.auto) {
          if (autofix && (!f.pb_at || c.now - Date.parse(f.pb_at) >= (pb.cooldown_ms || 0))) {
            f.pb_at = new Date(c.now).toISOString(); dirty = true; f.state = 'handling';
            const res = await execPlaybook(env, d, c, pb, f, { dry: false, triggered_by: 'brain', parent: run.id }).catch(e => ({ ok: false, did: String(e && e.message || e) }));
            L.log(`פלייבוק ${pb.id}: ${res.ok ? 'הצליח' : 'לא הצליח'} · ${res.did || ''} (ריצה ${res.run_id || '?'})`); run.count('fixed', res.ok ? 1 : 0);
          }
        } else if (pb && !pb.auto) {
          if (f.state !== 'needs_approval') { await createPending(env, d, c, pb, f, L.log); f.state = 'needs_approval'; dirty = true; run.count('pending'); }
        } else if (!pb && (ev.type === 'new' || ev.type === 'reopened' || !f.escalated_at || c.now - Date.parse(f.escalated_at) >= REALERT_MS)) {
          if (env.BRAIN_AGENT_HOOK && (!f.escalated_at || c.now - Date.parse(f.escalated_at) >= REALERT_MS)) {
            const r = await escalate(env, d, c, f, run.id).catch(e => ({ ok: false, why: String(e && e.message || e) }));
            f.escalated_at = new Date(c.now).toISOString(); dirty = true; run.count('escalated');
            L.log(`נשלח לסוכן (BRAIN_AGENT_HOOK): ${r.ok ? 'התקבל' : 'נכשל ' + (r.why || '')} · ריצת סוכן ${r.run_id || '?'}`);
          }
        }
      }
      if (dirty || ev.type === 'seen' && c.now - Date.parse(f.last_saved || 0) > H) { f.last_saved = new Date(c.now).toISOString(); await saveFinding(env, f); }
      idx.f[f.id] = { state: f.state, status: f.status, severity: f.severity, check_id: f.check_id, last_seen: f.last_seen, resolved_at: f.resolved_at };
    }
    /* keep the index small: resolved > 7 days drop out */
    for (const [id, m] of Object.entries(idx.f)) if (m.state === 'resolved' && m.resolved_at && c.now - Date.parse(m.resolved_at) > 7 * 86400e3) delete idx.f[id];
    await kput(env, P.index, idx);
    for (const n of c.notes) { await c.slack(n, false, { cls: 'info' }); L.log(n); }   /* notes are housekeeping → center + digest */
    await kput(env, P.last, { at: new Date(c.now).toISOString(), run_id: run.id, checks: checkState });
    const open = Object.values(idx.f).filter(m => m.state !== 'resolved');
    L.log(`סיכום: ${open.length} פתוחים (${open.filter(m => m.status === 'fail').length} חמורים), ${checks.length} בדיקות`);
    await L.flush(env);
    return { ok: true, checks: checks.length, open: open.length, events: events.filter(e => e.type !== 'seen').map(e => e.type + ':' + e.f.id) };
  }, { triggered_by: opts.triggered_by || 'cron' });
}

brain_fix.source:
export async function execPlaybook(env, d, c, pb, f, { dry, triggered_by, parent } = {}) {
  let out = null, rid = null;
  const res = await withRun(env, 'brain_fix:' + pb.id, async (run) => {
    rid = run.id;
    const L = makeLogger(run.id, 'brain_fix:' + pb.id);
    L.log(`פלייבוק ${pb.id} · ${pb.name_he} · ממצא ${f.id}${dry ? ' · תצוגה מקדימה' : ''}`);
    try { out = await pb.run(c, f, { dry: !!dry, log: L.log }); }
    catch (e) { L.log('נפל: ' + String(e && e.message || e)); await L.flush(env); throw e; }
    L.log(`תוצאה: ${out && out.ok ? 'ok' : 'לא הושלם'}${out && out.did ? ' · ' + out.did : ''}`);
    await L.flush(env);
    if (!dry && d.auditRecord) await d.auditRecord(env, { kind: 'admin', area: 'מוח', action: `🧠 פלייבוק ${pb.id}: ${(out && out.did) || (out && out.ok ? 'ok' : 'נכשל')}`, ok: !!(out && out.ok), review: !(out && out.ok), data: { playbook: pb.id, finding: f.id, run_id: run.id, triggered_by } }).catch(() => {});
    run.count(out && out.ok ? 'ok' : 'not_ok');
    if (!dry) await recordChange(env, { kind: 'brain', actor: /^manual:/.test(String(triggered_by || '')) ? actorOf(String(triggered_by).slice(7)) : 'brain',
      summary_he: `${/^manual:/.test(String(triggered_by || '')) ? 'אושר' : 'הופעל אוטומטית'}: ${pb.name_he} · ${f.title_he || f.id} → ${out && out.ok ? 'בוצע' : 'לא הושלם'}`,
      details: { playbook: pb.id, finding: f.id, decision: /^manual:/.test(String(triggered_by || '')) ? 'approved' : 'auto', ok: !!(out && out.ok), did: (out && out.did) || '', run_id: run.id, triggered_by: triggered_by || 'brain' } });
    return { ok: !!(out && out.ok), did: out && out.did, preview: out && out.preview };
  }, { triggered_by: triggered_by || 'brain', parent });
  return { ...res, run_id: rid };
}

brain_agent.source:
async function escalate(env, d, c, f, parentRun) {
  let out = { ok: false };
  await withRun(env, 'brain_agent', async (run) => {
    const L = makeLogger(run.id, 'brain_agent');
    L.log(`הסלמה לסוכן: ${f.title_he}`);
    const payload = { kind: 'ishur.brain.finding', finding: { id: f.id, check_id: f.check_id, status: f.status, severity: f.severity, title_he: f.title_he, detail: f.detail, evidence: f.evidence, first_seen: f.first_seen },
      run_id: run.id, brain_url: 'https://go.ishur.io/api/ops/brain', run_log_url: 'https://go.ishur.io/api/ops/run-log', rules: 'read-only on /api/ops/*; never send WhatsApp; write reasoning to run-log' };
    const headers = { 'Content-Type': 'application/json', ...(env.BRAIN_AGENT_HOOK_TOKEN ? { Authorization: 'Bearer ' + env.BRAIN_AGENT_HOOK_TOKEN } : {}) };
    const r = await fetch(env.BRAIN_AGENT_HOOK, { method: 'POST', headers, body: JSON.stringify(payload) }).catch(() => null);
    out = { ok: !!(r && r.ok), why: r ? 'http ' + r.status : 'unreachable', run_id: run.id };
    L.log(`hook: ${out.why}`); await L.flush(env);
    return { ok: out.ok, escalated: f.id };
  }, { triggered_by: 'brain', parent: parentRun });
  return out;
}

subevent_continue.source:
export async function continueSubevents(env, d) {
  if (await d.isOff(env, 'subevent_continue')) return { ok: true, skipped: 'off:subevent_continue' };
  const win = d.sendWindowState();
  if (!win.open || d.isNoContactDay(d.ilDate())) return { ok: true, skipped: 'window-closed', why: win.why || 'no-contact-day' };
  const all = await d.kvPrefix(env, 'subevent:').catch(() => ({}));
  const out = [];
  for (const [token, v] of Object.entries(all)) {
    let rec = null; try { rec = JSON.parse(v); } catch {}
    if (!rec || !rec.parent) continue;
    if (rec.completed_at) { const r = await continueReminder(env, { token, ...rec }, d); if (r) out.push(r); continue; }
    const sub = { token, ...rec };
    let started = !!rec.started_at;
    if (!started) started = Object.keys(await d.kvPrefix(env, `shsent:${token}:`).catch(() => ({}))).length > 0;
    if (!started) { out.push({ token: token.slice(0, 8), skipped: 'not-started' }); continue; }
    const cap = await d.guestCapacity(env).catch(() => ({ remaining: 0 }));
    const room = Math.max(0, Number(cap.remaining) || 0);
    if (!room) { out.push({ token: token.slice(0, 8), held: 'cap', remaining: 0 }); continue; }
    const r = await runSubeventSend(env, sub, { dry: false, max: Math.min(SUB_SLICE, room) }, d);
    if (r.deny || r.refused) { out.push({ token: token.slice(0, 8), refused: r.refused || r.error }); continue; }
    const c = r.counts || {};
    const row = { token: token.slice(0, 8), sent: c.sent || 0, failed: c.failed || 0, hold: c.hold || 0 };
    if (!rec.started_at) await markSub(env, sub, { started_at: new Date().toISOString(), started_by: 'legacy-marks' });
    if (!c.hold && !c.failed && !r.held_stop) {
      const total = Object.keys(await d.kvPrefix(env, `shsent:${token}:`).catch(() => ({}))).length;
      await markSub(env, sub, { completed_at: new Date().toISOString(), completed_sent: total });
      await d.recordChange(env, { kind: 'subevent', actor: 'system', summary_he: `${sub.name}: הושלם, נשלחו ${total}`, details: { token, parent: sub.parent, template: sub.template, sent: total } }).catch(() => {});
      await d.slackPost(env, `${sub.name}: הושלם, נשלחו ${total}`, { oneoff: true }).catch(() => {});   /* oneoff: completed once */
      row.completed = true; row.total = total;
    }
    out.push(row);
  }
  return { ok: true, subs: out };
}

subevent_reminder.source:
async function continueReminder(env, sub, d) {
  const nowIl = d.ilNow ? d.ilNow() : ilStamp();
  if (!reminderDue(sub, nowIl)) return sub.reminder_at && !sub.reminder_completed_at && !sub.reminder_cancelled_at ? { token: sub.token.slice(0, 8), phase: 'reminder', skipped: 'not-yet', at: sub.reminder_at } : null;
  const t8 = sub.token.slice(0, 8);
  if (await d.isOff(env, 'subevent_reminder')) return { token: t8, phase: 'reminder', skipped: 'off:subevent_reminder' };
  const cap = await d.guestCapacity(env).catch(() => ({ remaining: 0 }));
  const room = Math.max(0, Number(cap.remaining) || 0);
  if (!room) return { token: t8, phase: 'reminder', held: 'cap', remaining: 0 };
  const r = await runSubeventSend(env, sub, { dry: false, max: Math.min(SUB_SLICE, room), phase: 'reminder' }, d);
  if (r.deny || r.refused) return { token: t8, phase: 'reminder', refused: r.refused || r.error };
  const c = r.counts || {};
  const row = { token: t8, phase: 'reminder', sent: c.sent || 0, failed: c.failed || 0, hold: c.hold || 0 };
  if (!sub.reminder_started_at) await markSub(env, sub, { reminder_started_at: new Date().toISOString(), reminder_started_by: 'schedule' });
  if (!c.hold && !c.failed && !r.held_stop) {
    const total = Object.keys(await d.kvPrefix(env, `shrem:${sub.token}:`).catch(() => ({}))).length;
    await markSub(env, sub, { reminder_completed_at: new Date().toISOString(), reminder_sent: total });
    await d.recordChange(env, { kind: 'subevent', actor: 'system', summary_he: `${sub.name}: תזכורת הושלמה, נשלחו ${total}`, details: { token: sub.token, parent: sub.parent, phase: 'reminder', template: r.template, sent: total } }).catch(() => {});
    await d.slackPost(env, `${sub.name}: תזכורת הושלמה, נשלחו ${total}`, { oneoff: true }).catch(() => {});   /* oneoff: completed once */
    row.completed = true; row.total = total;
  }
  return row;
}

call_round_watch.source:
{ id: 'call_round_not_dialing', name_he: 'סבב שיחות: יש תור ואין חיוגים 60 דקות', every_min: 10, async run(c) {
  const clock = ilClock(c.now);
  if (clock.dow === 'Sat' || clock.h < 10 || clock.h >= 19) return [];
  const sinceOpen = (clock.h - 10) * 60 + clock.m;   /* minutes since 10:00 — the first ticks of the day are not a stall */
  if (sinceOpen < 20 || !c.d.buildCallQueue) return [];
  const raw = await c.snapshot(); if (!raw) return [];
  const { queue = [] } = c.d.buildCallQueue(raw) || {};
  const byTok = {};
  for (const g of queue) { const t = String(g.token || ''); if (t) (byTok[t] = byTok[t] || []).push(g); }
  if (!Object.keys(byTok).length) return [];
  const evRow = t => ((raw.events && raw.events.values) || []).find(e => String(e[1] || '').trim() === t) || null;
  const out = [];
  let shared = null;
  for (const [tok, gs] of Object.entries(byTok)) {
    const ev = evRow(tok);
    const [roundRaw, addon] = await Promise.all([kget(c.env, 'callround:' + tok), kget(c.env, 'callsaddon:' + tok)]);
    let round = null; try { round = JSON.parse(roundRaw || 'null'); } catch {}
    const planCalls = !!(ev && c.d.planKeyOf && c.d.planKeyOf(ev) !== 'basic');
    if (!round && !addon && !planCalls) continue;
    if (round && String(round.at || '') > c.today) continue;   /* the round is for a later day */
    const dialable = [];
    for (const g of gs) { if (!shouldDial(g, c.today)) continue; if (g.guest_id && await kget(c.env, `shirtry:${g.guest_id}:${c.today}`)) continue; dialable.push(g); }
    if (!dialable.length) continue;   /* everyone queued was already tried today — nothing to dial */
    const last = Date.parse((await kget(c.env, 'calllast:' + tok)) || '') || 0;
    if (last && c.now - last < 60 * MIN) continue;
    if (!shared) {
      const pacer = (await kjson(c.env, 'pacer:last')) || {};
      const win = c.d.callWindowState ? c.d.callWindowState() : { open: true };
      shared = {
        paused: await c.d.sendingPaused(c.env).catch(() => false),
        noContact: c.d.isNoContactDay ? !!c.d.isNoContactDay(c.today) : false,
        win, calls: pacer.calls || {}, pacerAt: pacer.at || '',
        killDispatch: !!(await kget(c.env, 'auto:off:shir_dispatch')), killPacer: !!(await kget(c.env, 'auto:off:d_pacer')),
        retell: !!(await kget(c.env, 'billretell')), noRetell: !c.env.RETELL_KEY || !c.env.SHIR_FROM,
        cap: c.d.dailyCallCap ? c.d.dailyCallCap(c.env) : 0, dialsToday: Number(await kget(c.env, 'dials:day:' + c.today)) || 0,
      };
    }
    const s = shared, why = [];
    if (s.noContact) why.push('יום ללא פניות (חג)');
    if (s.win && s.win.open === false) why.push('חלון החיוג סגור (' + (s.win.why || 'שעות') + ')');

